import React, { useState } from 'react';
import { Category, Product, StoreProfile } from '../types';
import { MOCK_STORES, MOCK_PRODUCTS } from '../constants';
import { MapVisualizer } from '../components/MapVisualizer';
import { Search, Star, Plus, Minus, ShoppingCart, MapPin, X } from 'lucide-react';

interface CustomerScreenProps {
  onLogout: () => void;
}

export const CustomerScreen: React.FC<CustomerScreenProps> = ({ onLogout }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [showCart, setShowCart] = useState(false);

  // Filter stores
  const filteredStores = selectedCategory === 'ALL' 
    ? MOCK_STORES 
    : MOCK_STORES.filter(s => s.category === selectedCategory);

  const activeStoreProducts = activeStore 
    ? MOCK_PRODUCTS.filter(p => p.storeId === activeStore.id) 
    : [];

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) {
        return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      }
      return [...prev, { product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.product.id !== productId));
  };

  const totalAmount = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  const deliveryFee = 200; // Fixed delivery fee for demo

  return (
    <div className="pb-20">
      {/* Header */}
      <header className="bg-white p-4 sticky top-0 z-30 shadow-sm flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-orange-600 rounded-lg flex items-center justify-center">
            <span className="text-white font-bold">K</span>
          </div>
          <div>
            <h1 className="font-bold text-slate-800 leading-tight">أهلاً بك</h1>
            <p className="text-xs text-slate-500 flex items-center">
              <MapPin className="w-3 h-3 ml-1" /> بئر العاتر، حي السلام
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            className="relative p-2 bg-slate-100 rounded-full hover:bg-slate-200 transition-colors"
            onClick={() => setShowCart(true)}
          >
            <ShoppingCart className="w-5 h-5 text-slate-700" />
            {cart.length > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center">
                {cart.length}
              </span>
            )}
          </button>
          <button onClick={onLogout} className="text-sm text-red-500 hover:text-red-700 font-medium">خروج</button>
        </div>
      </header>

      {!activeStore ? (
        // Home View
        <div className="p-4 space-y-6">
          {/* Map Section */}
          <div className="bg-white p-4 rounded-2xl shadow-sm">
            <div className="flex justify-between items-center mb-3">
              <h2 className="font-bold text-lg text-slate-800">المتاجر القريبة منك</h2>
            </div>
            <MapVisualizer userType="CUSTOMER" height="h-40" />
          </div>

          {/* Categories */}
          <div>
            <h2 className="font-bold text-lg text-slate-800 mb-3">التصنيفات</h2>
            <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
              {['ALL', ...Object.values(Category)].map((cat) => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategory(cat as Category | 'ALL')}
                  className={`px-4 py-2 rounded-full whitespace-nowrap text-sm font-medium transition-colors ${
                    selectedCategory === cat 
                    ? 'bg-orange-600 text-white shadow-lg shadow-orange-200' 
                    : 'bg-white text-slate-600 border border-slate-200'
                  }`}
                >
                  {cat === 'ALL' ? 'الكل' : cat}
                </button>
              ))}
            </div>
          </div>

          {/* Stores List */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredStores.map(store => (
              <div 
                key={store.id} 
                onClick={() => setActiveStore(store)}
                className="bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-shadow cursor-pointer group"
              >
                <div className="h-32 bg-slate-200 relative overflow-hidden">
                  <img src={store.image} alt={store.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                  <div className="absolute bottom-2 left-2 bg-white px-2 py-1 rounded-lg text-xs font-bold flex items-center shadow">
                    <Star className="w-3 h-3 text-yellow-400 fill-current ml-1" />
                    {store.rating}
                  </div>
                </div>
                <div className="p-4">
                  <h3 className="font-bold text-lg text-slate-800">{store.name}</h3>
                  <div className="flex justify-between items-center mt-1">
                    <span className="text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">{store.category}</span>
                    <span className="text-xs text-slate-400">{store.location}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        // Store Detail View
        <div className="p-4">
          <button 
            onClick={() => setActiveStore(null)} 
            className="mb-4 text-slate-600 flex items-center hover:text-orange-600"
          >
            <span className="text-lg ml-1">→</span> العودة للمتاجر
          </button>

          <div className="flex items-start gap-4 mb-6">
            <img src={activeStore.image} alt={activeStore.name} className="w-20 h-20 rounded-2xl object-cover shadow-sm" />
            <div>
              <h2 className="text-2xl font-bold text-slate-800">{activeStore.name}</h2>
              <p className="text-slate-500 text-sm mt-1">{activeStore.location}</p>
              <div className="flex items-center gap-1 mt-2">
                <Star className="w-4 h-4 text-yellow-400 fill-current" />
                <span className="font-bold text-slate-700">{activeStore.rating}</span>
                <span className="text-slate-400 text-xs">(120 تقييم)</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {activeStoreProducts.length > 0 ? activeStoreProducts.map(product => (
              <div key={product.id} className="bg-white p-3 rounded-2xl shadow-sm flex gap-3">
                <img src={product.image} alt={product.name} className="w-24 h-24 rounded-xl object-cover bg-slate-100" />
                <div className="flex-1 flex flex-col justify-between">
                  <div>
                    <h3 className="font-bold text-slate-800">{product.name}</h3>
                    <p className="text-xs text-slate-500 mt-1 line-clamp-2">{product.description}</p>
                  </div>
                  <div className="flex justify-between items-center mt-2">
                    <span className="font-bold text-orange-600">{product.price} د.ج</span>
                    <button 
                      onClick={(e) => { e.stopPropagation(); addToCart(product); }}
                      className="bg-slate-900 text-white p-2 rounded-full hover:bg-orange-600 transition-colors"
                    >
                      <Plus className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            )) : (
              <div className="col-span-full text-center py-10 text-slate-400">
                لا توجد منتجات في هذا المتجر حالياً
              </div>
            )}
          </div>
        </div>
      )}

      {/* Cart Modal */}
      {showCart && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4">
          <div className="bg-white w-full sm:max-w-md rounded-t-3xl sm:rounded-3xl shadow-2xl h-[80vh] flex flex-col animate-slide-up">
            <div className="p-5 border-b border-slate-100 flex justify-between items-center">
              <h2 className="font-bold text-xl text-slate-800">سلة المشتريات</h2>
              <button onClick={() => setShowCart(false)} className="p-2 hover:bg-slate-100 rounded-full">
                <X className="w-6 h-6 text-slate-500" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-5 space-y-4">
              {cart.length === 0 ? (
                <div className="text-center py-10">
                  <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <ShoppingCart className="w-10 h-10 text-slate-400" />
                  </div>
                  <p className="text-slate-500">السلة فارغة، أضف بعض المنتجات!</p>
                </div>
              ) : (
                cart.map((item, idx) => (
                  <div key={idx} className="flex justify-between items-center bg-slate-50 p-3 rounded-xl">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 bg-white rounded flex items-center justify-center font-bold text-slate-700 text-sm border shadow-sm">
                        x{item.quantity}
                      </div>
                      <div>
                        <h4 className="font-bold text-slate-800 text-sm">{item.product.name}</h4>
                        <span className="text-xs text-slate-500">{item.product.price} د.ج</span>
                      </div>
                    </div>
                    <button 
                      onClick={() => removeFromCart(item.product.id)}
                      className="text-red-500 hover:bg-red-50 p-1 rounded"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))
              )}
            </div>

            {cart.length > 0 && (
              <div className="p-5 border-t border-slate-100 bg-slate-50 rounded-b-3xl sm:rounded-b-3xl">
                <div className="space-y-2 mb-4">
                  <div className="flex justify-between text-slate-600 text-sm">
                    <span>المجموع الفرعي</span>
                    <span>{totalAmount} د.ج</span>
                  </div>
                  <div className="flex justify-between text-slate-600 text-sm">
                    <span>التوصيل (بئر العاتر)</span>
                    <span>{deliveryFee} د.ج</span>
                  </div>
                  <div className="flex justify-between font-bold text-lg text-slate-800 pt-2 border-t border-slate-200">
                    <span>الإجمالي (الدفع عند الاستلام)</span>
                    <span>{totalAmount + deliveryFee} د.ج</span>
                  </div>
                </div>
                <button 
                  onClick={() => {
                    alert("تم إرسال طلبك بنجاح! سيتم الاتصال بك من قبل الموصل.");
                    setCart([]);
                    setShowCart(false);
                    setActiveStore(null);
                  }}
                  className="w-full bg-orange-600 text-white py-3 rounded-xl font-bold hover:bg-orange-700 shadow-lg shadow-orange-200 transition-all active:scale-95"
                >
                  تأكيد الطلب
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

