import React, { useState } from 'react';
import { UserRole } from '../types';
import { ShoppingBag, Store, Bike, MapPin, ArrowRight, Loader2, Phone, Lock, User, CheckCircle2 } from 'lucide-react';

interface AuthScreenProps {
  onLogin: (role: UserRole) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    password: ''
  });

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
  };

  const handleBack = () => {
    setSelectedRole(null);
    setFormData({ name: '', phone: '', password: '' });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Basic validation
    if (!formData.phone || !formData.password || (authMode === 'REGISTER' && !formData.name)) {
      alert('يرجى ملء جميع الحقول المطلوبة');
      return;
    }

    setIsLoading(true);

    // Simulate Network Request
    setTimeout(() => {
      setIsLoading(false);
      if (selectedRole) {
        onLogin(selectedRole);
      }
    }, 1500);
  };

  // Render Role Selection View
  if (!selectedRole) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-orange-100 via-white to-orange-50 flex flex-col items-center justify-center p-4">
        <div className="text-center mb-10 animate-fade-in-up">
          <div className="bg-orange-600 w-24 h-24 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-orange-200 rotate-3 transform hover:rotate-6 transition-all duration-300">
            <MapPin className="text-white w-12 h-12" />
          </div>
          <h1 className="text-5xl font-bold text-slate-900 mb-3 font-cairo">كيمو <span className="text-orange-600">App</span></h1>
          <p className="text-lg text-slate-500 max-w-md mx-auto leading-relaxed">تطبيق التوصيل الأول في بئر العاتر. اطلب، بيع، أو وصل بكل سهولة.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl px-4">
          <RoleCard 
            icon={<ShoppingBag className="w-10 h-10" />}
            title="أنا زبون"
            desc="أريد تصفح المتاجر والطلب"
            color="blue"
            onClick={() => handleRoleSelect(UserRole.CUSTOMER)}
          />
          <RoleCard 
            icon={<Store className="w-10 h-10" />}
            title="أنا متجر"
            desc="أريد بيع منتجاتي"
            color="emerald"
            onClick={() => handleRoleSelect(UserRole.STORE)}
          />
          <RoleCard 
            icon={<Bike className="w-10 h-10" />}
            title="أنا موصل"
            desc="أريد توصيل الطلبات"
            color="orange"
            onClick={() => handleRoleSelect(UserRole.DRIVER)}
          />
        </div>

        <footer className="mt-16 text-slate-400 text-sm font-medium">
          جميع الحقوق محفوظة © 2024 تطبيق كيمو
        </footer>
      </div>
    );
  }

  // Render Login/Register Form
  const roleInfo = {
    [UserRole.CUSTOMER]: { label: 'زبون', color: 'text-blue-600', bg: 'bg-blue-50' },
    [UserRole.STORE]: { label: 'متجر', color: 'text-emerald-600', bg: 'bg-emerald-50' },
    [UserRole.DRIVER]: { label: 'موصل', color: 'text-orange-600', bg: 'bg-orange-50' },
  }[selectedRole];

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-scale-up">
        {/* Header */}
        <div className="p-6 pb-0">
          <button 
            onClick={handleBack}
            className="flex items-center text-slate-400 hover:text-slate-600 transition-colors mb-4 group"
          >
            <ArrowRight className="w-5 h-5 ml-1 group-hover:-translate-x-1 transition-transform" />
            <span>العودة</span>
          </button>

          <div className="mb-8">
            <h2 className="text-3xl font-bold text-slate-800 mb-2">
              {authMode === 'LOGIN' ? 'تسجيل الدخول' : 'إنشاء حساب جديد'}
            </h2>
            <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-sm font-bold ${roleInfo?.bg} ${roleInfo?.color}`}>
              <span className="w-2 h-2 rounded-full bg-current"></span>
              دخول بصفة {roleInfo?.label}
            </div>
          </div>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6 pt-0 space-y-5">
          {authMode === 'REGISTER' && (
            <div className="space-y-1">
              <label className="text-sm font-bold text-slate-700 mr-1">الاسم الكامل</label>
              <div className="relative">
                <input 
                  type="text" 
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full pl-4 pr-11 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500 focus:bg-white transition-all"
                  placeholder="محمد بن عبد الله"
                />
                <User className="absolute right-3 top-3.5 w-5 h-5 text-slate-400" />
              </div>
            </div>
          )}

          <div className="space-y-1">
            <label className="text-sm font-bold text-slate-700 mr-1">رقم الهاتف</label>
            <div className="relative">
              <input 
                type="tel" 
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                className="w-full pl-4 pr-11 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500 focus:bg-white transition-all dir-ltr text-right"
                placeholder="06 XX XX XX XX"
                dir="ltr"
              />
              <Phone className="absolute right-3 top-3.5 w-5 h-5 text-slate-400" />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-sm font-bold text-slate-700 mr-1">كلمة المرور</label>
            <div className="relative">
              <input 
                type="password" 
                value={formData.password}
                onChange={(e) => setFormData({...formData, password: e.target.value})}
                className="w-full pl-4 pr-11 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500 focus:bg-white transition-all"
                placeholder="••••••••"
              />
              <Lock className="absolute right-3 top-3.5 w-5 h-5 text-slate-400" />
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading}
            className="w-full bg-slate-900 text-white py-4 rounded-xl font-bold text-lg hover:bg-orange-600 transition-all shadow-lg hover:shadow-orange-200 active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2 mt-4"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-6 h-6 animate-spin" />
                جاري التحميل...
              </>
            ) : (
              authMode === 'LOGIN' ? 'دخول' : 'إنشاء حساب'
            )}
          </button>
        </form>

        {/* Footer */}
        <div className="p-6 bg-slate-50 border-t border-slate-100 text-center">
          <p className="text-slate-600 text-sm">
            {authMode === 'LOGIN' ? 'ليس لديك حساب؟' : 'لديك حساب بالفعل؟'}
            <button 
              onClick={() => setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN')}
              className="text-orange-600 font-bold hover:underline mr-1"
            >
              {authMode === 'LOGIN' ? 'أنشئ حساباً جديداً' : 'سجل دخولك'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

// Helper Component for Role Cards
const RoleCard = ({ icon, title, desc, color, onClick }: any) => {
  const colors = {
    blue: 'bg-blue-50 text-blue-600 hover:border-blue-200 hover:shadow-blue-100',
