};

import React from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';
import { BIR_EL_ATER_CENTER } from '../utils/helpers';
import { MOCK_STORES } from '../constants';

interface MapVisualizerProps {
  userType: 'CUSTOMER' | 'DRIVER' | 'STORE';
  height?: string;
}

// Custom Icons Configuration
const createCustomIcon = (colorClass: string, size = 20) => {
  return L.divIcon({
    html: `<div class="${colorClass} w-full h-full rounded-full border-2 border-white shadow-lg"></div>`,
    className: 'bg-transparent',
    iconSize: [size, size],
    iconAnchor: [size/2, size/2],
    popupAnchor: [0, -size/2]
  });
};

const userIcon = createCustomIcon('bg-blue-600 animate-pulse', 16);
const storeIcon = createCustomIcon('bg-emerald-500', 24);
const driverIcon = createCustomIcon('bg-orange-500', 18);

// Mock Drivers Data
const mockDrivers = [
  { id: 'd1', lat: 34.7510, lng: 8.0580 },
  { id: 'd2', lat: 34.7480, lng: 8.0650 },
];

// Component to handle map center updates if needed
const RecenterMap = ({ lat, lng }: { lat: number; lng: number }) => {
  const map = useMap();
  map.setView([lat, lng]);
  return null;
};

export const MapVisualizer: React.FC<MapVisualizerProps> = ({ userType, height = 'h-64' }) => {
  // Default center (Bir el-Ater)
  const center = [BIR_EL_ATER_CENTER.lat, BIR_EL_ATER_CENTER.lng] as L.LatLngExpression;

  return (
    <div className={`relative w-full ${height} rounded-xl overflow-hidden border-2 border-slate-300 shadow-inner isolation-isolate z-0`}>
      <MapContainer 
        center={center} 
        zoom={14} 
        scrollWheelZoom={false} 
        className="h-full w-full"
        style={{ background: '#e5e7eb' }}
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {/* User Location (Simulated Center) */}
        <Marker position={center} icon={userIcon}>
          <Popup>موقعك الحالي</Popup>
        </Marker>

        {/* Show Stores for Customers */}
        {userType === 'CUSTOMER' && MOCK_STORES.map((store) => (
          <Marker 
            key={store.id} 
            position={[store.coordinates.lat, store.coordinates.lng]} 
            icon={storeIcon}
          >
            <Popup>
              <div className="text-center">
                <strong className="block text-slate-800">{store.name}</strong>
                <span className="text-xs text-slate-500">{store.category}</span>
              </div>
            </Popup>
          </Marker>
        ))}

        {/* Show Drivers for Customers and Stores */}
        {userType !== 'DRIVER' && mockDrivers.map((driver) => (
          <Marker 
            key={driver.id} 
            position={[driver.lat, driver.lng]} 
            icon={driverIcon}
          >
            <Popup>سائق توصيل (متاح)</Popup>
          </Marker>
        ))}

      </MapContainer>

      {/* Overlay Badge */}
      <div className="absolute bottom-2 left-2 bg-white/90 p-1 px-2 rounded text-[10px] text-slate-500 shadow z-[400] pointer-events-none">
        خريطة بئر العاتر
      </div>
    </div>
  );
};

