import React, { useState, useMemo, useEffect } from 'react';
import { Category, Product, StoreProfile } from '../types';
import { MOCK_STORES, MOCK_PRODUCTS } from '../constants';
import { calculateDistance, calculateDeliveryFee, formatCurrency } from '../utils/helpers';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { Search, Star, Plus, Minus, ShoppingCart, MapPin, X, ShieldCheck, Bike, CheckCircle, ChevronLeft, Heart, Clock, ArrowRight } from 'lucide-react';

interface CustomerScreenProps {
  onLogout: () => void;
}

const USER_LOCATION = { lat: 34.7520, lng: 8.0550 };

export const CustomerScreen: React.FC<CustomerScreenProps> = ({ onLogout }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [showCart, setShowCart] = useState(false);
  const [activeOrderStage, setActiveOrderStage] = useState<number>(0);
  const [showRating, setShowRating] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);

  // Handle Scroll Effect for Header
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const storesWithDistance = useMemo(() => {
    return MOCK_STORES.map(store => ({
      ...store,
      distance: calculateDistance(USER_LOCATION, store.coordinates)
    })).sort((a, b) => a.distance - b.distance);
  }, []);

  const filteredStores = useMemo(() => {
    let result = storesWithDistance;
    if (selectedCategory !== 'ALL') {
      result = result.filter(s => s.category === selectedCategory);
    }
    if (searchQuery) {
      result = result.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));
    }
    return result;
  }, [selectedCategory, searchQuery, storesWithDistance]);

  const activeStoreProducts = activeStore 
    ? MOCK_PRODUCTS.filter(p => p.storeId === activeStore.id) 
    : [];

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) {
        return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      }
      return [...prev, { product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.product.id !== productId));
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
        if (item.product.id === productId) {
            return { ...item, quantity: Math.max(0, item.quantity + delta) };
        }
        return item;
    }).filter(item => item.quantity > 0));
  }

  const cartTotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  const deliveryDistance = activeStore ? calculateDistance(USER_LOCATION, activeStore.coordinates) : 
                           (cart.length > 0 ? calculateDistance(USER_LOCATION, MOCK_STORES.find(s => s.id === cart[0].product.storeId)!.coordinates) : 0);
  const deliveryFee = calculateDeliveryFee(deliveryDistance, cartTotal);
  const grandTotal = cartTotal + deliveryFee;

  const handlePlaceOrder = () => {
    setShowCart(false);
    setActiveOrderStage(1);
    setTimeout(() => setActiveOrderStage(2), 3000);
    setTimeout(() => setActiveOrderStage(3), 8000);
  };

  const closeOrderFlow = () => {
    setShowRating(true);
    setActiveOrderStage(0);
    setCart([]);
    setActiveStore(null);
  };

  // ORDER TRACKING SCREEN
  if (activeOrderStage > 0) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-brand-50 to-white opacity-50 z-0"></div>

        <div className="w-full max-w-md bg-white/80 backdrop-blur-xl rounded-[2.5rem] p-10 shadow-2xl border border-white z-10 text-center animate-scale-up">
           <div className="relative mb-8 mx-auto w-32 h-32">
             <div className="absolute inset-0 bg-brand-100 rounded-full animate-ping opacity-20"></div>
             <div className="relative bg-white w-32 h-32 rounded-full flex items-center justify-center shadow-lg border-4 border-brand-50">
               {activeOrderStage === 1 && <Search className="w-14 h-14 text-brand-500 animate-pulse" />}
               {activeOrderStage === 2 && <Bike className="w-14 h-14 text-blue-500 animate-float" />}
               {activeOrderStage === 3 && <CheckCircle className="w-14 h-14 text-emerald-500" />}
             </div>
           </div>

           <h2 className="text-3xl font-black text-slate-800 mb-3 font-cairo">
            {activeOrderStage === 1 && 'جاري البحث...'}
            {activeOrderStage === 2 && 'في الطريق!'}
            {activeOrderStage === 3 && 'وصل الطلب!'}
          </h2>

          <p className="text-slate-500 mb-8 font-medium leading-relaxed">
            {activeOrderStage === 1 && 'نبحث عن أقرب سائق في بئر العاتر لتوصيل طلبك بسرعة.'}
            {activeOrderStage === 2 && 'السائق محمد استلم طلبك وهو في طريقه إليك الآن.'}
            {activeOrderStage === 3 && 'شكراً لاستخدامك كيمو! يرجى استلام الطلب.'}
          </p>

          <div className="w-full bg-slate-100 rounded-full h-3 mb-8 overflow-hidden">
             <div 
                className="h-full bg-gradient-to-r from-brand-500 to-yellow-400 rounded-full transition-all duration-1000 ease-out shadow-[0_0_10px_rgba(249,115,22,0.5)]" 
                style={{ width: activeOrderStage === 1 ? '30%' : activeOrderStage === 2 ? '75%' : '100%' }}
             ></div>
          </div>

          {activeOrderStage === 3 && (
            <button onClick={closeOrderFlow} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl hover:scale-105 transition-transform">
              إتمام وتقييم
