                        </div>
                    ) : (
                        <div className="space-y-4">
                            {cart.map((item) => (
                                <div key={item.product.id} className="flex items-center gap-4 bg-slate-50 p-3 rounded-2xl">
                                    <img src={item.product.image} className="w-16 h-16 rounded-xl object-cover" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-slate-800">{item.product.name}</h4>
                                        <div className="flex items-center gap-1 text-brand-600 font-bold text-sm">
                                            {formatCurrency(item.product.price)}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 bg-white px-2 py-1 rounded-xl shadow-sm border border-slate-100">
                                        <button onClick={() => updateQuantity(item.product.id, -1)} className="p-1 hover:text-red-500"><Minus className="w-4 h-4"/></button>
                                        <span className="font-bold text-sm w-4 text-center">{item.quantity}</span>
                                        <button onClick={() => updateQuantity(item.product.id, 1)} className="p-1 hover:text-green-500"><Plus className="w-4 h-4"/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {cart.length > 0 && (
                    <div className="p-6 bg-slate-50 border-t border-slate-100 pb-8">
                        <div className="space-y-2 mb-6 text-sm font-medium text-slate-500">
                             <div className="flex justify-between"><span>المجموع</span> <span>{formatCurrency(cartTotal)}</span></div>
                             <div className="flex justify-between"><span>التوصيل</span> <span className="text-brand-600">{formatCurrency(deliveryFee)}</span></div>
                             <div className="flex justify-between text-lg font-black text-slate-900 pt-2 border-t border-slate-200 mt-2">
                                <span>الإجمالي</span> <span>{formatCurrency(grandTotal)}</span>
                             </div>
                        </div>
                        <button 
                            onClick={handlePlaceOrder}
