                                <img src={newProduct.image} alt="Preview" className="w-full h-full object-cover" />
                                {isUploading && (
                                <div className="absolute inset-0 bg-black/50 flex items-center justify-center z-20">
                                    <Loader2 className="w-10 h-10 text-white animate-spin" />
                                </div>
                                )}
                                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 backdrop-blur-sm z-10">
                                <button onClick={triggerFileInput} className="p-2 bg-white rounded-full hover:bg-brand-500 hover:text-white transition-colors"><Upload className="w-5 h-5" /></button>
                                <button onClick={removeImage} className="p-2 bg-white rounded-full hover:bg-red-500 hover:text-white transition-colors"><X className="w-5 h-5" /></button>
                                </div>
                            </div>
                        )}
                        </div>

                        <div className="group">
                        <label className="block text-sm font-bold text-slate-500 mb-2">اسم المنتج</label>
                        <input 
                            type="text" 
                            value={newProduct.name}
                            onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
                            className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-slate-700 bg-slate-50 focus:bg-white"
                            placeholder="مثال: بيتزا 4 فصول"
                        />
                        </div>

                        <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-2">السعر (د.ج)</label>
                            <input 
                            type="number" 
                            value={newProduct.price}
                            onChange={(e) => setNewProduct({...newProduct, price: Number(e.target.value)})}
                            className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-slate-700 bg-slate-50 focus:bg-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-2">التصنيف</label>
                            <div className="relative">
                                <select 
                                value={newProduct.category}
                                onChange={(e) => setNewProduct({...newProduct, category: e.target.value as Category})}
                                className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-slate-700 bg-slate-50 focus:bg-white appearance-none"
                                >
                                {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                                <ChevronRight className="absolute left-4 top-1/2 -translate-y-1/2 rotate-90 w-5 h-5 text-slate-400 pointer-events-none" />
                            </div>
                        </div>
                        </div>

                        <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                        <div className="flex justify-between items-center mb-3">
                            <label className="block text-sm font-bold text-slate-500">الوصف</label>
                            <button 
                            onClick={handleAIHelp}
                            disabled={isGenerating}
                            className="text-xs flex items-center gap-2 text-white font-bold bg-gradient-to-r from-purple-600 to-indigo-600 px-3 py-1.5 rounded-full hover:shadow-lg transition-all disabled:opacity-50"
                            >
                            <Sparkles className="w-3 h-3" /> 
                            {isGenerating ? 'جاري التفكير...' : 'اكتب لي يا ذكاء!'}
                            </button>
                        </div>
                        <textarea 
                            rows={4}
                            value={newProduct.description}
                            onChange={(e) => setNewProduct({...newProduct, description: e.target.value})}
                            className="w-full p-3 bg-white border border-slate-200 rounded-xl focus:border-purple-500 outline-none transition-colors text-sm"
                            placeholder="اكتب وصفاً أو اطلب من مساعد كيمو..."
                        ></textarea>
                        </div>

                        <div className="pt-4 flex gap-4">
                            <button 
                                onClick={() => setIsAddingProduct(false)}
                                className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold text-lg hover:bg-slate-200 transition-colors"
                            >
                                إلغاء
                            </button>
                            <button 
                                onClick={saveProduct}
                                className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg hover:bg-brand-600 transition-colors shadow-lg hover:shadow-xl active:scale-98"
                            >
                                حفظ المنتج
                            </button>
                        </div>
                    </div>
                </div>
            )}
          </div>
        )}

        {view === 'ORDERS' && (
          <div className="max-w-4xl mx-auto animate-fade-in-up">
            <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-2">
                <ClipboardList className="w-8 h-8 text-brand-600" /> الطلبات الواردة
            </h2>

            {orders.length === 0 ? (
                <div className="bg-white rounded-[2rem] p-16 text-center shadow-sm border border-slate-100">
                    <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6">
                        <ShoppingBag className="w-12 h-12 text-blue-300" />
                    </div>
                    <h3 className="text-xl font-bold text-slate-800 mb-2">لا توجد طلبات جديدة</h3>
                    <p className="text-slate-400">ستظهر الطلبات هنا عندما يقوم الزبائن بالشراء.</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {/* Order list would go here */}
                </div>
            )}
          </div>
        )}

        {view === 'SETTINGS' && (
          <div className="max-w-2xl mx-auto bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 animate-fade-in-up">
             <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-3">
                <Settings className="w-8 h-8 text-slate-400" /> إعدادات المتجر
              </h2>
              <div className="space-y-6">
                <div className="flex items-center gap-4 p-5 bg-blue-50/50 rounded-3xl text-blue-700 border border-blue-100">
                  <div className="bg-white p-3 rounded-xl shadow-sm"><MapPin className="w-6 h-6 text-blue-600" /></div>
                  <div>
                    <h3 className="font-bold text-lg">موقع المتجر (GPS)</h3>
                    <p className="text-xs opacity-80 font-medium mt-1">يستخدم لتحديد المسافة بينك وبين الزبائن</p>
                  </div>
                  <button className="mr-auto bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg shadow-blue-500/30 hover:bg-blue-700">تحديث</button>
                </div>
                <div>
                   <label className="block text-sm font-bold text-slate-500 mb-2">اسم المتجر</label>
                   <input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" defaultValue="مطعم السعادة" />
                </div>
                 <div>
                   <label className="block text-sm font-bold text-slate-500 mb-2">ساعات العمل</label>
                   <div className="flex gap-4">
                      <div className="flex-1 relative">
                          <span className="absolute -top-2 right-3 bg-white px-1 text-[10px] font-bold text-slate-400">من</span>
                          <input type="time" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" />
                      </div>
                      <div className="flex-1 relative">
                          <span className="absolute -top-2 right-3 bg-white px-1 text-[10px] font-bold text-slate-400">إلى</span>
                          <input type="time" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" />
                      </div>
                   </div>
                </div>
                <button className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold mt-4 hover:bg-slate-800 transition-colors">حفظ التغييرات</button>
              </div>
          </div>
        )}
      </main>
    </div>
  );
};

