import React, { useState, useEffect } from 'react';
import { UserRole } from './types';
import { AuthScreen } from './screens/AuthScreen';
import { CustomerScreen } from './screens/CustomerScreen';
import { StoreScreen } from './screens/StoreScreen';
import { DriverScreen } from './screens/DriverScreen';
import { auth, db } from './services/firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { ref, get } from 'firebase/database';
import { Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          // Fetch user role from Realtime Database
          const userRef = ref(db, `users/${user.uid}`);
          const snapshot = await get(userRef);

          if (snapshot.exists()) {
            const userData = snapshot.val();
            setCurrentRole(userData.role);
          } else {
            console.error("User data not found in database");
            setCurrentRole(null);
          }
        } catch (error) {
          console.error("Error fetching user data:", error);
          setCurrentRole(null);
        }
      } else {
        setCurrentRole(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setCurrentRole(null);
    } catch (error) {
      console.error("Error signing out:", error);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <Loader2 className="w-10 h-10 text-brand-600 animate-spin" />
      </div>
    );
  }

  const renderScreen = () => {
    switch (currentRole) {
      case UserRole.CUSTOMER:
        return <CustomerScreen onLogout={handleLogout} />;
      case UserRole.STORE:
        return <StoreScreen onLogout={handleLogout} />;
      case UserRole.DRIVER:
        return <DriverScreen onLogout={handleLogout} />;
      default:
        // Even if logged in but no role (edge case), show Auth or handle error
        // Here we just show AuthScreen (which handles "Login" state internally for the UI)
        return <AuthScreen onLogin={() => {}} />; 
    }
  };

  return (
    <div className="font-sans antialiased text-slate-900 bg-gray-50 min-h-screen">
       {renderScreen()}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole } from '../types';
import { auth, db } from '../services/firebase';
import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from 'firebase/auth';
import { ref, set } from 'firebase/database';
import { ShoppingBag, Store, Bike, MapPin, ArrowRight, Loader2, Phone, Lock, User, Mail, ChevronLeft } from 'lucide-react';

interface AuthScreenProps {
  onLogin: (role: UserRole) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
  };

  const handleBack = () => {
    setSelectedRole(null);
    setFormData({ name: '', email: '', phone: '', password: '' });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Basic validation
    if (!formData.email || !formData.password || (authMode === 'REGISTER' && (!formData.name || !formData.phone))) {
      alert('يرجى ملء جميع الحقول المطلوبة');
      return;
    }

    setIsLoading(true);

    try {
      if (authMode === 'REGISTER') {
        // 1. Create User in Firebase Auth
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;

        // 2. Save detailed profile in Realtime Database
        if (selectedRole) {
          await set(ref(db, 'users/' + user.uid), {
            name: formData.name,
            email: formData.email,
            phone: formData.phone,
            role: selectedRole,
            createdAt: Date.now()
          });

          // Trigger parent callback (optional, App.tsx listener handles the redirect mostly)
          onLogin(selectedRole);
        }

      } else {
        // Login Logic
        await signInWithEmailAndPassword(auth, formData.email, formData.password);
        // App.tsx onAuthStateChanged will handle the rest (fetching role and redirecting)
      }
    } catch (error: any) {
      console.error("Auth Error:", error);
      let message = "حدث خطأ غير متوقع";
      if (error.code === 'auth/email-already-in-use') message = "البريد الإلكتروني مستخدم بالفعل";
      else if (error.code === 'auth/wrong-password') message = "كلمة المرور غير صحيحة";
      else if (error.code === 'auth/user-not-found') message = "المستخدم غير موجود";
      else if (error.code === 'auth/invalid-email') message = "البريد الإلكتروني غير صالح";
      else if (error.code === 'auth/weak-password') message = "كلمة المرور ضعيفة جداً";

      alert(message);
    } finally {
      setIsLoading(false);
    }
  };

  // ----------------------------------------------------
  // ROLE SELECTION VIEW (Premium Design)
  // ----------------------------------------------------
  if (!selectedRole) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 flex flex-col items-center justify-center p-4 relative overflow-hidden">
        {/* Abstract Background Shapes */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
           <div className="absolute -top-[10%] -left-[10%] w-96 h-96 bg-brand-500/20 rounded-full blur-[100px] animate-pulse"></div>
           <div className="absolute top-[40%] -right-[10%] w-80 h-80 bg-blue-500/20 rounded-full blur-[100px]"></div>
        </div>

        <div className="z-10 text-center mb-12 animate-fade-in-up">
          <div className="relative inline-block">
            <div className="bg-gradient-to-br from-brand-500 to-red-600 w-28 h-28 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-brand-500/30 rotate-6 transform hover:rotate-12 transition-all duration-500 group cursor-default">
              <MapPin className="text-white w-14 h-14 drop-shadow-md group-hover:scale-110 transition-transform" />
            </div>
            <div className="absolute -bottom-2 -right-2 bg-white text-slate-900 text-xs font-bold px-3 py-1 rounded-full shadow-lg animate-bounce">
              بئر العاتر
            </div>
          </div>
          <h1 className="text-6xl font-black text-white mb-2 font-cairo tracking-tight">كيمو <span className="text-transparent bg-clip-text bg-gradient-to-r from-brand-500 to-yellow-400">App</span></h1>
          <p className="text-lg text-slate-300 max-w-md mx-auto leading-relaxed font-light">
            تطبيق التوصيل الأول. اطلب، بيع، أو وصل.
            <br/><span className="text-brand-400 font-medium">كل شيء بين يديك.</span>
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-5 w-full max-w-5xl px-4 z-10">
          <RoleCard 
            icon={<ShoppingBag className="w-8 h-8" />}
            title="أنا زبون"
            desc="تصفح واطلب من المتاجر"
            theme="blue"
            onClick={() => handleRoleSelect(UserRole.CUSTOMER)}
            delay="0ms"
          />
          <RoleCard 
            icon={<Store className="w-8 h-8" />}
            title="أنا متجر"
            desc="اعرض منتجاتك للبيع"
            theme="emerald"
            onClick={() => handleRoleSelect(UserRole.STORE)}
            delay="100ms"
          />
          <RoleCard 
            icon={<Bike className="w-8 h-8" />}
            title="أنا موصل"
            desc="وصل الطلبات واكسب"
            theme="orange"
            onClick={() => handleRoleSelect(UserRole.DRIVER)}
            delay="200ms"
          />
        </div>

        <div className="mt-12 text-slate-500 text-sm z-10 font-medium opacity-60">
          الإصدار 1.1.0 (Firebase Enabled)
        </div>
      </div>
    );
  }

  // ----------------------------------------------------
  // LOGIN / REGISTER FORM (Glassmorphism)
  // ----------------------------------------------------
  const roleConfig = {
    [UserRole.CUSTOMER]: { label: 'زبون', gradient: 'from-blue-500 to-indigo-600', icon: <ShoppingBag/> },
    [UserRole.STORE]: { label: 'متجر', gradient: 'from-emerald-500 to-teal-600', icon: <Store/> },
    [UserRole.DRIVER]: { label: 'موصل', gradient: 'from-orange-500 to-red-600', icon: <Bike/> },
  }[selectedRole];

  return (
    <div className={`min-h-screen bg-slate-50 flex items-center justify-center p-4 relative`}>
      {/* Dynamic Background Header */}
      <div className={`absolute top-0 left-0 w-full h-[50vh] bg-gradient-to-b ${roleConfig?.gradient} rounded-b-[3rem] shadow-2xl`}>
         <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
      </div>

      <div className="bg-white/90 backdrop-blur-xl w-full max-w-md rounded-3xl shadow-2xl overflow-hidden flex flex-col animate-scale-up z-10 border border-white/50 relative top-4">

        {/* Navigation & Header */}
        <div className="p-8 pb-4">
          <button 
            onClick={handleBack}
            className="flex items-center text-slate-500 hover:text-slate-800 transition-colors mb-6 group bg-slate-100 hover:bg-slate-200 px-3 py-1.5 rounded-full w-fit text-sm font-bold"
          >
            <ChevronLeft className="w-4 h-4 ml-1 group-hover:-translate-x-1 transition-transform" />
            تغيير الفئة
          </button>

          <div className="mb-2 flex items-center justify-between">
            <div>
              <h2 className="text-3xl font-black text-slate-800 mb-1">
                {authMode === 'LOGIN' ? 'مرحباً بعودتك' : 'حساب جديد'}
              </h2>
              <p className="text-slate-500 text-sm">سجل دخولك للمتابعة كـ <span className={`font-bold text-transparent bg-clip-text bg-gradient-to-r ${roleConfig?.gradient}`}>{roleConfig?.label}</span></p>
            </div>
            <div className={`w-12 h-12 rounded-2xl bg-gradient-to-br ${roleConfig?.gradient} flex items-center justify-center text-white shadow-lg`}>
              {React.cloneElement(roleConfig!.icon as React.ReactElement, { size: 24 })}
            </div>
          </div>
        </div>

        {/* Inputs */}
        <form onSubmit={handleSubmit} className="p-8 pt-2 space-y-4">
          {authMode === 'REGISTER' && (
            <div className="group">
              <label className="text-xs font-bold text-slate-500 mr-1 uppercase tracking-wider">الاسم الكامل</label>
              <div className="relative mt-1">
                <input 
                  type="text" 
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full pl-4 pr-12 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-brand-500 focus:bg-white transition-all font-bold text-slate-700"
                  placeholder="الاسم واللقب"
                />
                <User className="absolute right-4 top-3.5 w-5 h-5 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
              </div>
            </div>
          )}

          <div className="group">
            <label className="text-xs font-bold text-slate-500 mr-1 uppercase tracking-wider">البريد الإلكتروني</label>
            <div className="relative mt-1">
              <input 
                type="email" 
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
                className="w-full pl-4 pr-12 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-brand-500 focus:bg-white transition-all font-bold text-slate-700 dir-ltr text-right"
                placeholder="example@gmail.com"
                dir="ltr"
              />
              <Mail className="absolute right-4 top-3.5 w-5 h-5 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
            </div>
          </div>

          {authMode === 'REGISTER' && (
            <div className="group">
              <label className="text-xs font-bold text-slate-500 mr-1 uppercase tracking-wider">رقم الهاتف</label>
              <div className="relative mt-1">
                <input 
                  type="tel" 
                  value={formData.phone}
                  onChange={(e) => setFormData({...formData, phone: e.target.value})}
                  className="w-full pl-4 pr-12 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-brand-500 focus:bg-white transition-all font-bold text-slate-700 dir-ltr text-right"
                  placeholder="06 XX XX XX XX"
                  dir="ltr"
                />
                <Phone className="absolute right-4 top-3.5 w-5 h-5 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
              </div>
            </div>
          )}

          <div className="group">
            <label className="text-xs font-bold text-slate-500 mr-1 uppercase tracking-wider">كلمة المرور</label>
            <div className="relative mt-1">
              <input 
                type="password" 
                value={formData.password}
                onChange={(e) => setFormData({...formData, password: e.target.value})}
