          </div>

          <button 
            type="submit" 
            disabled={isLoading}
            className={`w-full bg-gradient-to-r ${roleConfig?.gradient} text-white py-4 rounded-2xl font-bold text-lg hover:shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2 mt-6 shadow-md shadow-slate-200`}
          >
            {isLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : (authMode === 'LOGIN' ? 'تسجيل الدخول' : 'إنشاء حساب')}
