import React, { useState, useEffect } from 'react';
import { UserRole } from './types';
import { AuthScreen } from './screens/AuthScreen';
import { CustomerScreen } from './screens/CustomerScreen';
import { StoreScreen } from './screens/StoreScreen';
import { DriverScreen } from './screens/DriverScreen';
import { auth, db } from './services/firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { ref, get } from 'firebase/database';
import { Loader2, AlertTriangle, ShieldAlert } from 'lucide-react';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole | null>(null);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          // Fetch user role from Realtime Database
          const userRef = ref(db, `users/${user.uid}`);
          const snapshot = await get(userRef);

          if (snapshot.exists()) {
            const userData = snapshot.val();
            setCurrentRole(userData.role);
          } else {
            console.error("User data not found in database");
            // If user exists in Auth but not in DB, we might want to let them register again or handle it
            // For now, staying at AuthScreen allow them to "Login" which triggers this check again, 
            // or "Register" which might fail if email taken. 
            // Ideally, we treat this as 'no role' so they see AuthScreen.
            setCurrentRole(null);
          }
          setDbError(null);
        } catch (error: any) {
          console.error("Error fetching user data:", error);
          if (error.code === 'PERMISSION_DENIED' || error.message.includes('PERMISSION_DENIED')) {
            setDbError("PERMISSION_DENIED");
          } else {
            setCurrentRole(null);
          }
        }
      } else {
        setCurrentRole(null);
        setDbError(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      setCurrentRole(null);
    } catch (error) {
      console.error("Error signing out:", error);
    }
  };

  if (dbError === 'PERMISSION_DENIED') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50 p-6 text-center">
        <div className="bg-white p-8 rounded-[2rem] shadow-xl max-w-md border border-red-100">
          <div className="w-20 h-20 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-6">
            <ShieldAlert className="w-10 h-10 text-red-500" />
          </div>
          <h2 className="text-2xl font-black text-slate-800 mb-2">تنبيه المطورين</h2>
          <p className="text-slate-600 mb-6 font-medium">
            تم رفض الوصول لقاعدة البيانات (Permission Denied).
            <br/>
            يجب تحديث <strong>Firebase Database Rules</strong> للسماح بالقراءة والكتابة.
          </p>

          <div className="bg-slate-900 text-left p-4 rounded-xl mb-6 overflow-x-auto" dir="ltr">
            <pre className="text-xs text-green-400 font-mono">
{`{
  "rules": {
    ".read": "auth != null",
    ".write": "auth != null"
  }
}`}
            </pre>
          </div>

          <button 
            onClick={() => window.location.reload()}
            className="w-full bg-red-500 text-white py-3 rounded-xl font-bold hover:bg-red-600 transition-colors"
          >
            تحديث الصفحة
          </button>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <Loader2 className="w-10 h-10 text-brand-600 animate-spin" />
      </div>
    );
  }

  const renderScreen = () => {
    switch (currentRole) {
      case UserRole.CUSTOMER:
        return <CustomerScreen onLogout={handleLogout} />;
      case UserRole.STORE:
        return <StoreScreen onLogout={handleLogout} />;
      case UserRole.DRIVER:
        return <DriverScreen onLogout={handleLogout} />;
      default:
        // Even if logged in but no role (edge case), show Auth or handle error
        // Here we just show AuthScreen (which handles "Login" state internally for the UI)
        return <AuthScreen onLogin={() => {}} />; 
    }
  };

  return (
    <div className="font-sans antialiased text-slate-900 bg-gray-50 min-h-screen">
       {renderScreen()}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole } from '../types';
import { auth, db } from '../services/firebase';
import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from 'firebase/auth';
import { ref, set } from 'firebase/database';
import { ShoppingBag, Store, Bike, MapPin, ArrowRight, Loader2, Phone, Lock, User, Mail, ChevronLeft, AlertCircle } from 'lucide-react';

interface AuthScreenProps {
  onLogin: (role: UserRole) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });
  const [error, setError] = useState('');

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
    setError('');
  };

  const handleBack = () => {
    setSelectedRole(null);
    setFormData({ name: '', email: '', phone: '', password: '' });
    setError('');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Basic validation
    if (!formData.email || !formData.password || (authMode === 'REGISTER' && (!formData.name || !formData.phone))) {
      setError('يرجى ملء جميع الحقول المطلوبة');
      return;
    }

    setIsLoading(true);

    try {
      if (authMode === 'REGISTER') {
        // 1. Create User in Firebase Auth
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;

        // 2. Save detailed profile in Realtime Database
        if (selectedRole) {
          // This step will fail if Database Rules are locked (PERMISSION_DENIED)
          await set(ref(db, 'users/' + user.uid), {
            name: formData.name,
            email: formData.email,
            phone: formData.phone,
            role: selectedRole,
            createdAt: Date.now()
          });

          // Trigger parent callback (optional, App.tsx listener handles the redirect mostly)
          onLogin(selectedRole);
        }

      } else {
        // Login Logic
        await signInWithEmailAndPassword(auth, formData.email, formData.password);
        // App.tsx onAuthStateChanged will handle the rest (fetching role and redirecting)
      }
    } catch (err: any) {
      // Handle Firebase Errors gracefully
      let message = "حدث خطأ غير متوقع";

      // Check for Database Permission Error specifically
      if (err.code === 'PERMISSION_DENIED' || (err.message && err.message.includes('PERMISSION_DENIED'))) {
         message = "خطأ في الصلاحيات: تأكد من إعداد Firebase Realtime Database Rules على وضع الاختبار أو السماح للمستخدمين المسجلين.";
         console.error("Database Permission Denied. Check your Firebase Console Rules.");
      } else {
        switch (err.code) {
          case 'auth/invalid-credential':
          case 'auth/user-not-found':
          case 'auth/wrong-password':
            message = "البريد الإلكتروني أو كلمة المرور غير صحيحة";
            break;
          case 'auth/email-already-in-use':
            message = "البريد الإلكتروني مستخدم بالفعل";
            break;
          case 'auth/invalid-email':
            message = "البريد الإلكتروني غير صالح";
            break;
          case 'auth/weak-password':
            message = "كلمة المرور ضعيفة جداً (يجب أن تكون 6 أحرف على الأقل)";
            break;
          case 'auth/network-request-failed':
              message = "تحقق من اتصالك بالإنترنت";
              break;
          case 'auth/too-many-requests':
              message = "تم تعطيل الحساب مؤقتاً بسبب كثرة المحاولات الفاشلة. حاول لاحقاً.";
              break;
          default:
            console.error("Auth Error:", err); 
            message = `حدث خطأ: ${err.message}`;
        }
      }

      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  // ----------------------------------------------------
  // ROLE SELECTION VIEW (Premium Design)
  // ----------------------------------------------------
  if (!selectedRole) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 flex flex-col items-center justify-center p-4 relative overflow-hidden">
