import React, { useState, useEffect } from 'react';
import { UserRole } from './types';
import { AuthScreen } from './screens/AuthScreen';
import { CustomerScreen } from './screens/CustomerScreen';
import { StoreScreen } from './screens/StoreScreen';
import { DriverScreen } from './screens/DriverScreen';
import { auth, db } from './services/firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { ref, get } from 'firebase/database';
import { Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          // 1. Try to fetch user role from Realtime Database
          const userRef = ref(db, `users/${user.uid}`);
          const snapshot = await get(userRef);

          if (snapshot.exists()) {
            const userData = snapshot.val();
            setCurrentRole(userData.role);
            // Sync with local storage for future fallbacks
            localStorage.setItem('kimo_user_role', userData.role);
          } else {
            // 2. If not in DB (or permissions fail silently), check Local Storage
            fallbackToLocalRole();
          }
        } catch (error: any) {
          console.warn("Database access failed (Permissions/Network), using Local Storage fallback.");
          fallbackToLocalRole();
        }
      } else {
        // User is signed out
        setCurrentRole(null);
        localStorage.removeItem('kimo_user_role');
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const fallbackToLocalRole = () => {
    const savedRole = localStorage.getItem('kimo_user_role') as UserRole;
    if (savedRole) {
      setCurrentRole(savedRole);
    } else {
      // Valid auth but no role found anywhere -> Show Auth Screen to re-select/login
      setCurrentRole(null);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      localStorage.removeItem('kimo_user_role');
      setCurrentRole(null);
    } catch (error) {
      console.error("Error signing out:", error);
    }
  };

  const handleManualLogin = (role: UserRole) => {
    // Called by AuthScreen when user logs in/registers successfully
    // This ensures immediate UI update even if DB listeners are slow or fail
    localStorage.setItem('kimo_user_role', role);
    setCurrentRole(role);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <Loader2 className="w-10 h-10 text-brand-600 animate-spin" />
      </div>
    );
  }

  const renderScreen = () => {
    switch (currentRole) {
      case UserRole.CUSTOMER:
        return <CustomerScreen onLogout={handleLogout} />;
      case UserRole.STORE:
        return <StoreScreen onLogout={handleLogout} />;
      case UserRole.DRIVER:
        return <DriverScreen onLogout={handleLogout} />;
      default:
        // Pass the manual login handler to update state immediately
        return <AuthScreen onLogin={handleManualLogin} />; 
    }
  };

  return (
    <div className="font-sans antialiased text-slate-900 bg-gray-50 min-h-screen">
       {renderScreen()}
    </div>
  );
};

export default App;

