          if (snapshot.exists()) {
            const userData = snapshot.val();
            setCurrentRole(userData.role);
            setUserName(userData.name || 'مستخدم');

            // Sync with local storage
            localStorage.setItem('kimo_user_role', userData.role);
            localStorage.setItem('kimo_user_name', userData.name);
          } else {
            // 2. Fallback to Local Storage
            fallbackToLocalData();
          }
        } catch (error: any) {
          console.warn("Database access failed, using Local Storage fallback.");
          fallbackToLocalData();
        }
      } else {
        // User is signed out
        setCurrentRole(null);
        setUserName('');
        localStorage.removeItem('kimo_user_role');
        // We might keep the name for UX, but usually clear it on logout
        localStorage.removeItem('kimo_user_name');
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const fallbackToLocalData = () => {
    const savedRole = localStorage.getItem('kimo_user_role') as UserRole;
    const savedName = localStorage.getItem('kimo_user_name');

    if (savedRole) {
      setCurrentRole(savedRole);
    } else {
      setCurrentRole(null);
    }

    if (savedName) {
      setUserName(savedName);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      localStorage.removeItem('kimo_user_role');
      localStorage.removeItem('kimo_user_name');
      setCurrentRole(null);
      setUserName('');
    } catch (error) {
      console.error("Error signing out:", error);
    }
  };

  const handleManualLogin = (role: UserRole, name?: string) => {
    // Called by AuthScreen for immediate update
    localStorage.setItem('kimo_user_role', role);
    setCurrentRole(role);

    if (name) {
      localStorage.setItem('kimo_user_name', name);
      setUserName(name);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <Loader2 className="w-10 h-10 text-brand-600 animate-spin" />
      </div>
    );
  }

  const renderScreen = () => {
    switch (currentRole) {
      case UserRole.CUSTOMER:
        return <CustomerScreen userName={userName} onLogout={handleLogout} />;
      case UserRole.STORE:
        return <StoreScreen userName={userName} onLogout={handleLogout} />;
      case UserRole.DRIVER:
        return <DriverScreen userName={userName} onLogout={handleLogout} />;
      default:
        return <AuthScreen onLogin={handleManualLogin} />; 
    }
  };

  return (
    <div className="font-sans antialiased text-slate-900 bg-gray-50 min-h-screen">
       {renderScreen()}
    </div>
  );
};

