    setIsLoading(true);

    try {
      if (authMode === 'REGISTER') {
        // 1. Create User in Firebase Auth
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;

        // 2. Try to Save profile in Realtime Database (Role Specific Path)
        if (selectedRole) {
          // Important: Save to LocalStorage immediately as fallback
          localStorage.setItem('kimo_user_name', formData.name);
          localStorage.setItem('kimo_user_role', selectedRole);

          const dbPath = getDatabasePath(selectedRole);

          try {
            await set(ref(db, `${dbPath}/${user.uid}`), {
              name: formData.name,
              email: formData.email,
              phone: formData.phone,
              role: selectedRole,
              createdAt: Date.now()
            });
          } catch (dbError) {
            console.warn("Database write failed (likely permissions), continuing with Local Storage.");
          }

          // Always succeed locally
          onLogin(selectedRole, formData.name);
