import CryptoJS from 'crypto-js';

interface StoreScreenProps {
  onLogout: () => void;
  userName: string;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({ onLogout, userName }) => {
  const [view, setView] = useState<'PRODUCTS' | 'ORDERS' | 'SETTINGS'>('PRODUCTS');

  // State for managing products list
  const [myProducts, setMyProducts] = useState<Product[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(true);

  // Mock Orders State
  const [orders, setOrders] = useState<Order[]>([]);

  // Toggle between List and Add Form within Products view
  const [isAddingProduct, setIsAddingProduct] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    description: '',
    price: 0,
    category: Category.FOOD,
    image: ''
  });

  // Listen to products from Firebase AND LocalStorage
  useEffect(() => {
    const productsRef = ref(db, 'products');

    const unsubscribe = onValue(productsRef, (snapshot) => {
      const dbProducts: Product[] = [];
      const data = snapshot.val();
      if (data) {
        dbProducts.push(...(Object.values(data) as Product[]));
      }

      // Merge with Local Storage Products (Fallback)
      const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');

      // Combine and filter by store_1 (Demo ID)
      const allProducts = [...dbProducts, ...localProducts].filter((p: any) => p.storeId === 'store_1');

      setMyProducts(allProducts.reverse()); // Show newest first
      setLoadingProducts(false);
    }, (error) => {
      console.warn("Firebase read failed (Permission), loading local only.", error);
      // Fallback: Load only local products if DB fails
      const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
      const filtered = localProducts.filter((p: any) => p.storeId === 'store_1');
      setMyProducts(filtered.reverse());
      setLoadingProducts(false);
    });

    return () => unsubscribe();
  }, []);

  const handleAIHelp = async () => {
    if (!newProduct.name || !newProduct.category) {
      alert("الرجاء إدخال اسم المنتج وتصنيفه أولاً.");
      return;
    }
    setIsGenerating(true);
    const desc = await generateProductDescription(newProduct.name, newProduct.category);
    setNewProduct(prev => ({ ...prev, description: desc }));
    setIsGenerating(false);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        // 1. Show local preview
        const reader = new FileReader();
        reader.onloadend = () => {
          setNewProduct(prev => ({ ...prev, image: reader.result as string }));
        };
        reader.readAsDataURL(file);

        // 2. Upload to Cloudinary
        setIsUploading(true);
        try {
            const cloudName = 'dkqxgwjnr';
            const apiKey = '486896193791285';
            const apiSecret = 'gB5nJivH0GpZQ5jyXcrQ3QhPLSw';

            const timestamp = Math.round((new Date()).getTime() / 1000);
            const signature = CryptoJS.SHA1(`timestamp=${timestamp}${apiSecret}`).toString();

            const formData = new FormData();
            formData.append('file', file);
            formData.append('api_key', apiKey);
            formData.append('timestamp', timestamp.toString());
            formData.append('signature', signature);

            const response = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();
            if (data.secure_url) {
                setNewProduct(prev => ({ ...prev, image: data.secure_url }));
                console.log('Upload successful:', data.secure_url);
            } else {
                alert('فشل رفع الصورة: ' + (data.error?.message || 'خطأ غير معروف'));
            }
        } catch (error) {
            console.error('Error uploading image:', error);
            alert('حدث خطأ أثناء الاتصال بالخادم.');
        } finally {
            setIsUploading(false);
        }
    }
  };

  const saveProduct = async () => {
    if (!newProduct.name || !newProduct.price || !newProduct.image) {
      alert("يرجى إكمال بيانات المنتج والصورة");
      return;
    }

    setIsSaving(true);

    // Generate ID locally first to use in fallback if needed
    const tempId = `prod_${Date.now()}`; 

    const productData: Product = {
      id: tempId, // Will be overwritten if DB write succeeds with push key
      name: newProduct.name!,
      description: newProduct.description || '',
      price: newProduct.price!,
      category: newProduct.category || Category.FOOD,
      image: newProduct.image!,
      storeId: 'store_1' // Hardcoded for this demo
    };

    try {
      // Try Create a reference for the new product in Firebase
      const newProductRef = push(ref(db, 'products'));
      const dbId = newProductRef.key;

      if (dbId) {
          productData.id = dbId;
          await set(newProductRef, productData);
          alert("تم حفظ المنتج بنجاح في قاعدة البيانات!");
      } else {
          throw new Error("Could not generate DB ID");
      }

    } catch (error: any) {
      console.warn("Firebase write failed (Permission denied?), saving locally.", error);

      // Fallback: Save to LocalStorage
      const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
      localProducts.push(productData);
      localStorage.setItem('kimo_local_products', JSON.stringify(localProducts));

      // Update State Manually since onValue won't trigger for local storage
      setMyProducts(prev => [productData, ...prev]);

      alert("تم حفظ المنتج محلياً (بسبب قيود الصلاحيات)");
    } finally {
      setIsSaving(false);
      setIsAddingProduct(false);
      setNewProduct({ name: '', description: '', price: 0, category: Category.FOOD, image: '' });
    }
  };

  const deleteProduct = async (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المنتج؟')) {
      // 1. Try deleting from Firebase
      try {
        await remove(ref(db, `products/${id}`));
      } catch (error) {
        console.warn("Firebase delete failed, trying local delete.");
      }

      // 2. Always delete from LocalStorage as well (covers fallback products)
      const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
      const updatedLocal = localProducts.filter((p: any) => p.id !== id);
