import React, { useState, useMemo, useEffect } from 'react';
import { Category, Product, StoreProfile } from '../types';
import { MOCK_STORES } from '../constants';
import { calculateDistance, calculateDeliveryFee, formatCurrency, BIR_EL_ATER_CENTER } from '../utils/helpers';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { db } from '../services/firebase';
import { ref, onValue } from 'firebase/database';
import { Search, Star, Plus, Minus, ShoppingCart, ShoppingBag, MapPin, X, ShieldCheck, Bike, CheckCircle, ChevronLeft, Heart, Clock, ArrowRight, Loader2 } from 'lucide-react';

interface CustomerScreenProps {
  onLogout: () => void;
  userName: string;
}

const USER_LOCATION = { lat: 34.7520, lng: 8.0550 };

export const CustomerScreen: React.FC<CustomerScreenProps> = ({ onLogout, userName }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [activeStoreProducts, setActiveStoreProducts] = useState<Product[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [showCart, setShowCart] = useState(false);
  const [activeOrderStage, setActiveOrderStage] = useState<number>(0);
  const [showRating, setShowRating] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);

  // New state for Real Stores
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [loadingStores, setLoadingStores] = useState(true);

  // Handle Scroll Effect for Header
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Fetch REAL Stores from Firebase
  useEffect(() => {
    const storesRef = ref(db, 'stores');
    const unsubscribe = onValue(storesRef, (snapshot) => {
        const data = snapshot.val();
        if (data) {
            const loadedStores: StoreProfile[] = Object.keys(data).map(key => {
                const storeData = data[key];
                // Map Firebase Data to StoreProfile UI Model
                return {
                    id: key, // This is the User UID
                    name: storeData.name || 'متجر بدون اسم',
                    // Default values for fields not yet in registration form
                    rating: 4.5, // New stores get a good start rating
                    reviewCount: 0,
                    isVerified: true,
                    category: Category.FOOD, // Default category, store needs settings to change this
                    location: 'بئر العاتر',
                    // Randomize location slightly around center so they don't overlap on map
                    coordinates: { 
                        lat: BIR_EL_ATER_CENTER.lat + (Math.random() - 0.5) * 0.01, 
                        lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.01 
                    },
                    image: `https://picsum.photos/200/200?random=${key}` // Placeholder image
                };
            });
            setStores(loadedStores);
        } else {
            setStores([]);
        }
        setLoadingStores(false);
    });
    return () => unsubscribe();
  }, []);

  // Fetch products from Firebase AND LocalStorage
  useEffect(() => {
    if (activeStore) {
      setLoadingProducts(true);
      const productsRef = ref(db, 'products');

      const unsubscribe = onValue(productsRef, (snapshot) => {
        let allProducts: Product[] = [];
        const data = snapshot.val();
        if (data) {
          allProducts = Object.values(data) as Product[];
        }

        // Merge Local Products (fallback for testing on same device)
        const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
        allProducts = [...allProducts, ...localProducts];

        // Strict Filtering by Store UID
        const storeProducts = allProducts.filter((p: any) => p.storeId === activeStore.id);

        setActiveStoreProducts(storeProducts);
        setLoadingProducts(false);
      }, (err) => {
         // Fallback on read error
         console.warn("DB read error, using local fallback", err);
         const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
         const storeProducts = localProducts.filter((p: any) => p.storeId === activeStore.id) as Product[];
         setActiveStoreProducts(storeProducts);
         setLoadingProducts(false);
      });

      return () => unsubscribe();
    } else {
      setActiveStoreProducts([]);
    }
  }, [activeStore]);

  const storesWithDistance = useMemo(() => {
    return stores.map(store => ({
      ...store,
      distance: calculateDistance(USER_LOCATION, store.coordinates)
    })).sort((a, b) => a.distance - b.distance);
  }, [stores]);

  const filteredStores = useMemo(() => {
    let result = storesWithDistance;
    if (selectedCategory !== 'ALL') {
      result = result.filter(s => s.category === selectedCategory);
    }
    if (searchQuery) {
      result = result.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));
    }
    return result;
  }, [selectedCategory, searchQuery, storesWithDistance]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) {
        return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      }
      return [...prev, { product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.product.id !== productId));
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
        if (item.product.id === productId) {
            return { ...item, quantity: Math.max(0, item.quantity + delta) };
        }
        return item;
    }).filter(item => item.quantity > 0));
  }

  const cartTotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  // Calculate delivery distance based on current cart or active store
  const getDeliveryDistance = () => {
      if (activeStore) return calculateDistance(USER_LOCATION, activeStore.coordinates);
      if (cart.length > 0) {
          const storeId = cart[0].product.storeId;
          const store = stores.find(s => s.id === storeId);
          return store ? calculateDistance(USER_LOCATION, store.coordinates) : 0;
      }
      return 0;
  }

  const deliveryDistance = getDeliveryDistance();
  const deliveryFee = calculateDeliveryFee(deliveryDistance, cartTotal);
  const grandTotal = cartTotal + deliveryFee;

  const handlePlaceOrder = () => {
    setShowCart(false);
    setActiveOrderStage(1);
    setTimeout(() => setActiveOrderStage(2), 3000);
    setTimeout(() => setActiveOrderStage(3), 8000);
  };

  const closeOrderFlow = () => {
    setShowRating(true);
    setActiveOrderStage(0);
    setCart([]);
    setActiveStore(null);
  };

  // ORDER TRACKING SCREEN
  if (activeOrderStage > 0) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-brand-50 to-white opacity-50 z-0"></div>

        <div className="w-full max-w-md bg-white/80 backdrop-blur-xl rounded-[2.5rem] p-10 shadow-2xl border border-white z-10 text-center animate-scale-up">
           <div className="relative mb-8 mx-auto w-32 h-32">
             <div className="absolute inset-0 bg-brand-100 rounded-full animate-ping opacity-20"></div>
             <div className="relative bg-white w-32 h-32 rounded-full flex items-center justify-center shadow-lg border-4 border-brand-50">
               {activeOrderStage === 1 && <Search className="w-14 h-14 text-brand-500 animate-pulse" />}
               {activeOrderStage === 2 && <Bike className="w-14 h-14 text-blue-500 animate-float" />}
               {activeOrderStage === 3 && <CheckCircle className="w-14 h-14 text-emerald-500" />}
             </div>
           </div>

           <h2 className="text-3xl font-black text-slate-800 mb-3 font-cairo">
            {activeOrderStage === 1 && 'جاري البحث...'}
            {activeOrderStage === 2 && 'في الطريق!'}
            {activeOrderStage === 3 && 'وصل الطلب!'}
          </h2>

          <p className="text-slate-500 mb-8 font-medium leading-relaxed">
            {activeOrderStage === 1 && 'نبحث عن أقرب سائق في بئر العاتر لتوصيل طلبك بسرعة.'}
            {activeOrderStage === 2 && 'السائق محمد استلم طلبك وهو في طريقه إليك الآن.'}
            {activeOrderStage === 3 && 'شكراً لاستخدامك كيمو! يرجى استلام الطلب.'}
          </p>

          <div className="w-full bg-slate-100 rounded-full h-3 mb-8 overflow-hidden">
             <div 
                className="h-full bg-gradient-to-r from-brand-500 to-yellow-400 rounded-full transition-all duration-1000 ease-out shadow-[0_0_10px_rgba(249,115,22,0.5)]" 
                style={{ width: activeOrderStage === 1 ? '30%' : activeOrderStage === 2 ? '75%' : '100%' }}
             ></div>
          </div>

          {activeOrderStage === 3 && (
            <button onClick={closeOrderFlow} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl hover:scale-105 transition-transform">
              إتمام وتقييم
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="bg-slate-50 min-h-screen pb-28">
      {showRating && <RatingModal type="STORE" targetName={activeStore?.name || "المتجر"} onClose={() => setShowRating(false)} />}

      {/* Floating Header */}
      <header className={`fixed top-0 left-0 right-0 z-40 transition-all duration-300 ${scrolled ? 'glass shadow-lg py-2' : 'bg-transparent py-4'}`}>
        <div className="container max-w-lg mx-auto px-4 flex items-center justify-between">
          {!activeStore ? (
             <div className="flex items-center gap-3">
               <div className="w-10 h-10 bg-brand-600 rounded-xl flex items-center justify-center shadow-lg shadow-brand-500/30">
                 <span className="text-white font-black text-xl">K</span>
               </div>
               <div className={`transition-opacity duration-300 ${scrolled ? 'opacity-0 w-0 overflow-hidden' : 'opacity-100'}`}>
                 <h1 className="font-bold text-slate-800 text-lg leading-none">مرحباً، {userName || 'زائر'}</h1>
                 <p className="text-xs text-slate-500 flex items-center mt-1">
                   <MapPin className="w-3 h-3 ml-1 text-brand-500" /> حي السلام، بئر العاتر
                 </p>
               </div>
             </div>
          ) : (
             <button onClick={() => setActiveStore(null)} className="flex items-center gap-2 bg-white/50 px-3 py-2 rounded-xl backdrop-blur-md">
                <ChevronLeft className="w-5 h-5 text-slate-700" />
                <span className="font-bold text-slate-700">العودة</span>
             </button>
          )}

          <div className="flex items-center gap-2">
            {!activeStore && (
                <button onClick={onLogout} className="w-10 h-10 bg-white rounded-full flex items-center justify-center text-slate-400 hover:text-red-500 shadow-sm border border-slate-100">
                    <X className="w-5 h-5" />
                </button>
            )}
            {activeStore && (
              <button 
                  className="relative w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center shadow-lg hover:bg-brand-600 transition-colors"
                  onClick={() => setShowCart(true)}
              >
                  <ShoppingCart className="w-6 h-6 text-white" />
                  {cart.length > 0 && (
                  <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-5 h-5 rounded-full flex items-center justify-center border-2 border-white font-bold animate-scale-up">
                      {cart.length}
                  </span>
                  )}
              </button>
            )}
          </div>
        </div>
      </header>

      {/* MAIN CONTENT */}
      <div className="container max-w-lg mx-auto pt-20 px-4">

        {!activeStore ? (
          <div className="space-y-8 animate-fade-in-up">

            {/* Search Bar */}
            <div className="relative group">
               <input 
                  type="text" 
                  placeholder="ابحث عن مطعم، أكلة، أو متجر..." 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-white border-none rounded-2xl py-4 pl-4 pr-12 shadow-sm text-slate-700 font-bold focus:ring-2 focus:ring-brand-500 focus:shadow-lg transition-all placeholder:font-normal placeholder:text-slate-400"
               />
               <Search className="absolute right-4 top-4 w-6 h-6 text-slate-400 group-focus-within:text-brand-500 transition-colors" />
            </div>

            {/* Map Snippet */}
            <div className="bg-white p-2 rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
                <div className="flex justify-between items-center px-4 py-2">
                   <h2 className="font-bold text-slate-800">بالقرب منك</h2>
                   <span className="text-xs text-brand-600 font-bold bg-brand-50 px-2 py-1 rounded-lg cursor-pointer">عرض الخريطة الكاملة</span>
                </div>
                <div className="rounded-[1.5rem] overflow-hidden">
                   <MapVisualizer userType="CUSTOMER" height="h-32" />
                </div>
            </div>

            {/* Categories - Horizontal Scroll */}
            <div>
              <div className="flex items-center justify-between mb-4">
                 <h2 className="font-bold text-xl text-slate-800">الأقسام</h2>
              </div>
              <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide snap-x">
                {['ALL', ...Object.values(Category)].map((cat, idx) => (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat as Category | 'ALL')}
                    className={`snap-start shrink-0 px-6 py-3 rounded-2xl whitespace-nowrap text-sm font-bold transition-all duration-300 ${
                      selectedCategory === cat 
                      ? 'bg-slate-900 text-white shadow-lg shadow-slate-900/20 scale-105' 
                      : 'bg-white text-slate-500 border border-slate-100 hover:border-brand-200 hover:text-brand-600'
                    }`}
                  >
                    {cat === 'ALL' ? 'الكل' : cat}
                  </button>
                ))}
              </div>
            </div>

            {/* Stores Grid */}
            <div className="space-y-4">
                <h2 className="font-bold text-xl text-slate-800">المتاجر المتاحة</h2>

                {loadingStores ? (
                    <div className="flex justify-center items-center h-40">
                         <Loader2 className="w-8 h-8 text-brand-500 animate-spin" />
                    </div>
                ) : filteredStores.length === 0 ? (
                    <div className="text-center py-10 bg-white rounded-3xl border border-dashed border-slate-200">
                        <Store className="w-12 h-12 text-slate-300 mx-auto mb-2" />
                        <p className="text-slate-500 font-bold">لا توجد متاجر مسجلة حالياً</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 gap-6 pb-4">
                        {filteredStores.map((store, idx) => (
                        <div 
                            key={store.id} 
                            onClick={() => setActiveStore(store)}
                            className="bg-white rounded-[2rem] overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 cursor-pointer group border border-slate-100"
                        >
                            <div className="h-40 bg-slate-200 relative overflow-hidden">
                                <img src={store.image} alt={store.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-60"></div>

                                {/* Floating Badges */}
                                <div className="absolute top-3 right-3 flex gap-2">
                                    {store.isVerified && (
                                        <div className="bg-blue-500/90 backdrop-blur-sm text-white p-1.5 rounded-full shadow-md">
                                            <ShieldCheck className="w-4 h-4" />
                                        </div>
                                    )}
                                </div>
                                <div className="absolute bottom-3 right-3 text-white">
                                    <h3 className="font-bold text-xl leading-none mb-1">{store.name}</h3>
                                    <p className="text-xs opacity-80 font-light flex items-center gap-1">
                                        <MapPin className="w-3 h-3" /> {store.location}
                                    </p>
                                </div>
                                <div className="absolute bottom-3 left-3 bg-white/20 backdrop-blur-md border border-white/30 text-white px-3 py-1 rounded-xl text-xs font-bold flex items-center gap-1">
                                    <Star className="w-3 h-3 text-yellow-400 fill-yellow-400" /> {store.rating}
                                </div>
                            </div>

                            <div className="p-5 flex justify-between items-center">
                                <div className="flex gap-3">
                                    <div className="bg-slate-50 px-3 py-1.5 rounded-xl text-xs font-bold text-slate-500 border border-slate-100">
                                        {store.category}
                                    </div>
                                    <div className="bg-orange-50 px-3 py-1.5 rounded-xl text-xs font-bold text-orange-600 flex items-center gap-1">
                                        <Clock className="w-3 h-3" /> 25 دقيقة
                                    </div>
                                </div>
                                <span className="text-sm font-bold text-slate-900">{store.distance} كم</span>
                            </div>
                        </div>
                        ))}
                    </div>
                )}
            </div>
          </div>
        ) : (
          // STORE DETAIL VIEW
          <div className="animate-fade-in-up pb-10">
            {/* Store Hero */}
            <div className="relative h-56 rounded-[2.5rem] overflow-hidden shadow-lg mb-8 group">
                <img src={activeStore.image} alt={activeStore.name} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent"></div>
                <div className="absolute bottom-6 right-6 text-white z-10">
                    <h2 className="text-4xl font-black mb-2">{activeStore.name}</h2>
                    <div className="flex items-center gap-4 text-sm font-medium opacity-90">
                         <span className="flex items-center gap-1"><Star className="w-4 h-4 text-yellow-400 fill-current" /> {activeStore.rating} ({activeStore.reviewCount} تقييم)</span>
                         <span className="w-1 h-1 bg-white rounded-full"></span>
                         <span>{activeStore.category}</span>
                    </div>
                </div>
            </div>

            <div className="flex items-center justify-between mb-6">
                 <h3 className="font-bold text-xl text-slate-800">المنتجات</h3>
            </div>

            {/* Products List */}
            <div className="space-y-4">
              {loadingProducts ? (
                <div className="flex justify-center items-center py-20">
                    <Loader2 className="w-8 h-8 text-brand-500 animate-spin" />
                </div>
              ) : activeStoreProducts.length > 0 ? (
                activeStoreProducts.map((product, idx) => (
                    <div key={product.id} 
                        className="bg-white p-4 rounded-3xl shadow-sm border border-slate-50 flex gap-4 transition-all hover:shadow-lg hover:-translate-y-1 group"
                        style={{ animationDelay: `${idx * 50}ms` }}
                    >
                    <div className="w-28 h-28 shrink-0 rounded-2xl overflow-hidden bg-slate-100">
                        <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    </div>
                    <div className="flex-1 flex flex-col justify-between py-1">
                        <div>
                        <h3 className="font-bold text-lg text-slate-800 leading-tight mb-1">{product.name}</h3>
                        <p className="text-xs text-slate-500 line-clamp-2 leading-relaxed">{product.description}</p>
                        </div>
                        <div className="flex justify-between items-end mt-2">
                        <span className="font-black text-xl text-brand-600">{formatCurrency(product.price)}</span>
                        <button 
                            onClick={(e) => { e.stopPropagation(); addToCart(product); }}
                            className="bg-slate-900 text-white w-10 h-10 rounded-full hover:bg-brand-600 transition-colors shadow-lg shadow-slate-900/20 flex items-center justify-center active:scale-90"
                        >
                            <Plus className="w-5 h-5" />
                        </button>
                        </div>
                    </div>
                    </div>
                ))
              ) : (
                <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-slate-300">
                    <ShoppingBag className="w-12 h-12 text-slate-300 mx-auto mb-3" />
                    <p className="text-slate-400 font-medium">لا توجد منتجات حالياً لهذا المتجر</p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Modern Cart Bottom Sheet */}
      {showCart && (
        <>
            <div className="fixed inset-0 bg-slate-900/60 z-50 backdrop-blur-sm transition-opacity" onClick={() => setShowCart(false)}></div>
            <div className="fixed bottom-0 left-0 right-0 z-[60] bg-white rounded-t-[2.5rem] shadow-[0_-10px_40px_rgba(0,0,0,0.1)] max-h-[85vh] flex flex-col animate-slide-up">

                {/* Drag Handle */}
                <div className="w-full flex justify-center pt-4 pb-2" onClick={() => setShowCart(false)}>
                    <div className="w-12 h-1.5 bg-slate-200 rounded-full"></div>
                </div>

                <div className="p-6 flex-1 overflow-y-auto">
                    <div className="flex justify-between items-center mb-6">
                         <h2 className="text-2xl font-black text-slate-800">سلة المشتريات</h2>
                         <span className="bg-brand-100 text-brand-700 font-bold px-3 py-1 rounded-xl text-sm">{cart.length} منتجات</span>
                    </div>

                    {cart.length === 0 ? (
                        <div className="text-center py-10 opacity-50">
                            <ShoppingCart className="w-16 h-16 mx-auto mb-4 text-slate-400" />
                            <p>سلتك فارغة</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {cart.map((item) => (
                                <div key={item.product.id} className="flex items-center gap-4 bg-slate-50 p-3 rounded-2xl">
                                    <img src={item.product.image} className="w-16 h-16 rounded-xl object-cover" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-slate-800">{item.product.name}</h4>
                                        <div className="flex items-center gap-1 text-brand-600 font-bold text-sm">
                                            {formatCurrency(item.product.price)}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 bg-white px-2 py-1 rounded-xl shadow-sm border border-slate-100">
                                        <button onClick={() => updateQuantity(item.product.id, -1)} className="p-1 hover:text-red-500"><Minus className="w-4 h-4"/></button>
                                        <span className="font-bold text-sm w-4 text-center">{item.quantity}</span>
                                        <button onClick={() => updateQuantity(item.product.id, 1)} className="p-1 hover:text-green-500"><Plus className="w-4 h-4"/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {cart.length > 0 && (
                    <div className="p-6 bg-slate-50 border-t border-slate-100 pb-8">
                        <div className="space-y-2 mb-6 text-sm font-medium text-slate-500">
                             <div className="flex justify-between"><span>المجموع</span> <span>{formatCurrency(cartTotal)}</span></div>
                             <div className="flex justify-between"><span>التوصيل</span> <span className="text-brand-600">{formatCurrency(deliveryFee)}</span></div>
                             <div className="flex justify-between text-lg font-black text-slate-900 pt-2 border-t border-slate-200 mt-2">
                                <span>الإجمالي</span> <span>{formatCurrency(grandTotal)}</span>
                             </div>
                        </div>
                        <button 
                            onClick={handlePlaceOrder}
                            className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg hover:bg-brand-600 transition-colors shadow-xl shadow-slate-900/20 flex items-center justify-center gap-2 group"
                        >
                            <span>تأكيد الطلب</span>
                            <ArrowRight className="w-5 h-5 group-hover:translate-x-[-4px] transition-transform" />
                        </button>
                    </div>
                )}
            </div>
        </>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Category, Product, StoreProfile } from '../types';
import { MOCK_STORES } from '../constants';
import { calculateDistance, calculateDeliveryFee, formatCurrency, BIR_EL_ATER_CENTER } from '../utils/helpers';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { db } from '../services/firebase';
import { ref, onValue } from 'firebase/database';
import { Search, Star, Plus, Minus, ShoppingCart, ShoppingBag, MapPin, X, ShieldCheck, Bike, CheckCircle, ChevronLeft, Heart, Clock, ArrowRight, Loader2, Store } from 'lucide-react';

interface CustomerScreenProps {
  onLogout: () => void;
  userName: string;
}

const USER_LOCATION = { lat: 34.7520, lng: 8.0550 };

export const CustomerScreen: React.FC<CustomerScreenProps> = ({ onLogout, userName }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [activeStoreProducts, setActiveStoreProducts] = useState<Product[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [showCart, setShowCart] = useState(false);
  const [activeOrderStage, setActiveOrderStage] = useState<number>(0);
  const [showRating, setShowRating] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);

  // New state for Real Stores
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [loadingStores, setLoadingStores] = useState(true);

  // Handle Scroll Effect for Header
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Fetch REAL Stores from Firebase
  useEffect(() => {
    const storesRef = ref(db, 'stores');
    const unsubscribe = onValue(storesRef, (snapshot) => {
        const data = snapshot.val();
        if (data) {
            const loadedStores: StoreProfile[] = Object.keys(data).map(key => {
                const storeData = data[key];
                // Map Firebase Data to StoreProfile UI Model
                return {
                    id: key, // This is the User UID
                    name: storeData.name || 'متجر بدون اسم',
                    // Default values for fields not yet in registration form
                    rating: 4.5, // New stores get a good start rating
                    reviewCount: 0,
                    isVerified: true,
                    category: Category.FOOD, // Default category, store needs settings to change this
                    location: 'بئر العاتر',
                    // Randomize location slightly around center so they don't overlap on map
                    coordinates: { 
                        lat: BIR_EL_ATER_CENTER.lat + (Math.random() - 0.5) * 0.01, 
                        lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.01 
                    },
                    image: `https://picsum.photos/200/200?random=${key}` // Placeholder image
                };
            });
            setStores(loadedStores);
        } else {
            setStores([]);
        }
        setLoadingStores(false);
    });
    return () => unsubscribe();
  }, []);

  // Fetch products from Firebase AND LocalStorage
  useEffect(() => {
    if (activeStore) {
      setLoadingProducts(true);
      const productsRef = ref(db, 'products');

      const unsubscribe = onValue(productsRef, (snapshot) => {
        let allProducts: Product[] = [];
        const data = snapshot.val();
        if (data) {
          allProducts = Object.values(data) as Product[];
        }

        // Merge Local Products (fallback for testing on same device)
        const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
        allProducts = [...allProducts, ...localProducts];

        // Strict Filtering by Store UID
        const storeProducts = allProducts.filter((p: any) => p.storeId === activeStore.id);

        setActiveStoreProducts(storeProducts);
        setLoadingProducts(false);
      }, (err) => {
         // Fallback on read error
         console.warn("DB read error, using local fallback", err);
         const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
         const storeProducts = localProducts.filter((p: any) => p.storeId === activeStore.id) as Product[];
         setActiveStoreProducts(storeProducts);
         setLoadingProducts(false);
      });

      return () => unsubscribe();
    } else {
      setActiveStoreProducts([]);
    }
  }, [activeStore]);

  const storesWithDistance = useMemo(() => {
    return stores.map(store => ({
      ...store,
      distance: calculateDistance(USER_LOCATION, store.coordinates)
    })).sort((a, b) => a.distance - b.distance);
  }, [stores]);

  const filteredStores = useMemo(() => {
    let result = storesWithDistance;
    if (selectedCategory !== 'ALL') {
      result = result.filter(s => s.category === selectedCategory);
    }
    if (searchQuery) {
      result = result.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));
    }
    return result;
  }, [selectedCategory, searchQuery, storesWithDistance]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) {
        return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      }
      return [...prev, { product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(item => item.product.id !== productId));
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
        if (item.product.id === productId) {
            return { ...item, quantity: Math.max(0, item.quantity + delta) };
        }
        return item;
    }).filter(item => item.quantity > 0));
  }

  const cartTotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  // Calculate delivery distance based on current cart or active store
  const getDeliveryDistance = () => {
      if (activeStore) return calculateDistance(USER_LOCATION, activeStore.coordinates);
      if (cart.length > 0) {
          const storeId = cart[0].product.storeId;
          const store = stores.find(s => s.id === storeId);
          return store ? calculateDistance(USER_LOCATION, store.coordinates) : 0;
      }
      return 0;
  }

  const deliveryDistance = getDeliveryDistance();
  const deliveryFee = calculateDeliveryFee(deliveryDistance, cartTotal);
  const grandTotal = cartTotal + deliveryFee;

  const handlePlaceOrder = () => {
    setShowCart(false);
    setActiveOrderStage(1);
    setTimeout(() => setActiveOrderStage(2), 3000);
    setTimeout(() => setActiveOrderStage(3), 8000);
  };

  const closeOrderFlow = () => {
    setShowRating(true);
    setActiveOrderStage(0);
    setCart([]);
    setActiveStore(null);
  };

  // ORDER TRACKING SCREEN
  if (activeOrderStage > 0) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-brand-50 to-white opacity-50 z-0"></div>

        <div className="w-full max-w-md bg-white/80 backdrop-blur-xl rounded-[2.5rem] p-10 shadow-2xl border border-white z-10 text-center animate-scale-up">
           <div className="relative mb-8 mx-auto w-32 h-32">
             <div className="absolute inset-0 bg-brand-100 rounded-full animate-ping opacity-20"></div>
