          </div>

          {authMode === 'REGISTER' && (
            <div className="group">
              <label className="text-xs font-bold text-slate-500 mr-1 uppercase tracking-wider">رقم الهاتف</label>
              <div className="relative mt-1">
                <input 
                  type="tel" 
                  value={formData.phone}
                  onChange={(e) => setFormData({...formData, phone: e.target.value})}
                  className="w-full pl-4 pr-12 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-brand-500 focus:bg-white transition-all font-bold text-slate-700 dir-ltr text-right"
