          )}

          <div className="group">
            <label className="text-xs font-bold text-slate-500 mr-1 uppercase tracking-wider">كلمة المرور</label>
            <div className="relative mt-1">
              <input 
                type="password" 
                value={formData.password}
                onChange={(e) => setFormData({...formData, password: e.target.value})}
                className="w-full pl-4 pr-12 py-3 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:outline-none focus:border-brand-500 focus:bg-white transition-all font-bold text-slate-700"
                placeholder="••••••••"
              />
              <Lock className="absolute right-4 top-3.5 w-5 h-5 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
            </div>
          </div>

          <button 
            type="submit" 
            disabled={isLoading}
            className={`w-full bg-gradient-to-r ${roleConfig?.gradient} text-white py-4 rounded-2xl font-bold text-lg hover:shadow-xl hover:scale-[1.02] active:scale-[0.98] transition-all disabled:opacity-70 disabled:cursor-not-allowed flex items-center justify-center gap-2 mt-6 shadow-md shadow-slate-200`}
