            ) : (
                <div className="space-y-4">
                    {/* Order list would go here */}
                </div>
            )}
          </div>
        )}

        {view === 'SETTINGS' && (
          <div className="max-w-2xl mx-auto bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 animate-fade-in-up">
             <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-3">
                <Settings className="w-8 h-8 text-slate-400" /> إعدادات المتجر
              </h2>
              <div className="space-y-6">
                <div className="flex items-center gap-4 p-5 bg-blue-50/50 rounded-3xl text-blue-700 border border-blue-100">
                  <div className="bg-white p-3 rounded-xl shadow-sm"><MapPin className="w-6 h-6 text-blue-600" /></div>
                  <div>
                    <h3 className="font-bold text-lg">موقع المتجر (GPS)</h3>
                    <p className="text-xs opacity-80 font-medium mt-1">يستخدم لتحديد المسافة بينك وبين الزبائن</p>
                  </div>
                  <button className="mr-auto bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg shadow-blue-500/30 hover:bg-blue-700">تحديث</button>
                </div>
                <div>
                   <label className="block text-sm font-bold text-slate-500 mb-2">اسم المتجر</label>
                   <input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" defaultValue={userName} />
                </div>
                 <div>
                   <label className="block text-sm font-bold text-slate-500 mb-2">ساعات العمل</label>
                   <div className="flex gap-4">
                      <div className="flex-1 relative">
                          <span className="absolute -top-2 right-3 bg-white px-1 text-[10px] font-bold text-slate-400">من</span>
                          <input type="time" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" />
                      </div>
                      <div className="flex-1 relative">
                          <span className="absolute -top-2 right-3 bg-white px-1 text-[10px] font-bold text-slate-400">إلى</span>
                          <input type="time" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" />
                      </div>
                   </div>
                </div>
                <button className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold mt-4 hover:bg-slate-800 transition-colors">حفظ التغييرات</button>
              </div>
