            {authMode === 'LOGIN' ? 'جديد في كيمو؟' : 'لديك حساب؟'}
            <button 
              onClick={() => {
                setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN');
                setError('');
              }}
