import { ref, push, set, onValue, remove } from 'firebase/database';
import { Sparkles, Package, Plus, Settings, MapPin, Store as StoreIcon, ChevronRight, Upload, X, Loader2, Trash2, Edit, ArrowLeft, ClipboardList, ShoppingBag } from 'lucide-react';
