            ) : (
                // ADD FORM VIEW
                <div className="bg-white p-8 rounded-[2rem] shadow-lg border border-slate-100 relative overflow-hidden animate-scale-up">
                    <div className="flex items-center gap-4 mb-8">
                        <button 
                            onClick={() => setIsAddingProduct(false)}
                            className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center hover:bg-slate-100"
                        >
                            <ArrowLeft className="w-5 h-5 text-slate-600" />
                        </button>
                        <h2 className="text-2xl font-black text-slate-800">إضافة منتج جديد</h2>
                    </div>

                    <div className="space-y-6 relative z-10">
                        {/* Image Upload Section */}
                        <div>
                        <label className="block text-sm font-bold text-slate-500 mb-2">صورة المنتج</label>
                        <input 
                            type="file" 
                            ref={fileInputRef}
                            onChange={handleImageUpload}
                            accept="image/*"
                            className="hidden"
                        />
                        {!newProduct.image ? (
                            <div 
                                onClick={triggerFileInput}
                                className="w-full h-48 border-2 border-dashed border-slate-300 rounded-2xl flex flex-col items-center justify-center cursor-pointer hover:border-brand-500 hover:bg-brand-50/50 transition-all group"
                            >
                                {isUploading ? (
                                    <div className="flex flex-col items-center animate-pulse">
                                        <Loader2 className="w-10 h-10 text-brand-500 animate-spin mb-2" />
                                        <p className="text-brand-600 font-bold text-sm">جاري رفع الصورة...</p>
                                    </div>
                                ) : (
                                    <>
                                        <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                                        <Upload className="w-8 h-8 text-slate-400 group-hover:text-brand-500" />
                                        </div>
                                        <p className="text-slate-500 font-bold group-hover:text-brand-600">اضغط لرفع صورة</p>
                                        <p className="text-xs text-slate-400 mt-1">PNG, JPG حتى 5MB</p>
                                    </>
                                )}
                            </div>
                        ) : (
                            <div className="relative w-full h-48 rounded-2xl overflow-hidden shadow-md group border border-slate-200">
                                <img src={newProduct.image} alt="Preview" className="w-full h-full object-cover" />
                                {isUploading && (
                                <div className="absolute inset-0 bg-black/50 flex items-center justify-center z-20">
                                    <Loader2 className="w-10 h-10 text-white animate-spin" />
                                </div>
                                )}
                                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 backdrop-blur-sm z-10">
                                <button onClick={triggerFileInput} className="p-2 bg-white rounded-full hover:bg-brand-500 hover:text-white transition-colors"><Upload className="w-5 h-5" /></button>
                                <button onClick={removeImage} className="p-2 bg-white rounded-full hover:bg-red-500 hover:text-white transition-colors"><X className="w-5 h-5" /></button>
                                </div>
                            </div>
                        )}
                        </div>

                        <div className="group">
                        <label className="block text-sm font-bold text-slate-500 mb-2">اسم المنتج</label>
                        <input 
                            type="text" 
                            value={newProduct.name}
                            onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
                            className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-slate-700 bg-slate-50 focus:bg-white"
                            placeholder="مثال: بيتزا 4 فصول"
                        />
                        </div>

                        <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-2">السعر (د.ج)</label>
                            <input 
                            type="number" 
                            value={newProduct.price}
                            onChange={(e) => setNewProduct({...newProduct, price: Number(e.target.value)})}
                            className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-slate-700 bg-slate-50 focus:bg-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-slate-500 mb-2">التصنيف</label>
                            <div className="relative">
                                <select 
                                value={newProduct.category}
                                onChange={(e) => setNewProduct({...newProduct, category: e.target.value as Category})}
                                className="w-full p-4 border-2 border-slate-100 rounded-2xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-slate-700 bg-slate-50 focus:bg-white appearance-none"
                                >
                                {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                                <ChevronRight className="absolute left-4 top-1/2 -translate-y-1/2 rotate-90 w-5 h-5 text-slate-400 pointer-events-none" />
                            </div>
                        </div>
                        </div>

                        <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                        <div className="flex justify-between items-center mb-3">
                            <label className="block text-sm font-bold text-slate-500">الوصف</label>
                            <button 
                            onClick={handleAIHelp}
                            disabled={isGenerating}
                            className="text-xs flex items-center gap-2 text-white font-bold bg-gradient-to-r from-purple-600 to-indigo-600 px-3 py-1.5 rounded-full hover:shadow-lg transition-all disabled:opacity-50"
                            >
                            <Sparkles className="w-3 h-3" /> 
                            {isGenerating ? 'جاري التفكير...' : 'اكتب لي يا ذكاء!'}
                            </button>
                        </div>
                        <textarea 
                            rows={4}
                            value={newProduct.description}
                            onChange={(e) => setNewProduct({...newProduct, description: e.target.value})}
                            className="w-full p-3 bg-white border border-slate-200 rounded-xl focus:border-purple-500 outline-none transition-colors text-sm"
                            placeholder="اكتب وصفاً أو اطلب من مساعد كيمو..."
                        ></textarea>
                        </div>

                        <div className="pt-4 flex gap-4">
                            <button 
                                onClick={() => setIsAddingProduct(false)}
                                className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold text-lg hover:bg-slate-200 transition-colors"
                            >
                                إلغاء
                            </button>
                            <button 
                                onClick={saveProduct}
                                disabled={isSaving || isUploading}
                                className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg hover:bg-brand-600 transition-colors shadow-lg hover:shadow-xl active:scale-98 disabled:opacity-50 disabled:cursor-not-allowed flex justify-center gap-2"
                            >
                                {isSaving ? <Loader2 className="animate-spin" /> : 'حفظ ونشر'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
          </div>
        )}

        {view === 'ORDERS' && (
          <div className="max-w-4xl mx-auto animate-fade-in-up">
            <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-2">
                <ClipboardList className="w-8 h-8 text-brand-600" /> الطلبات الواردة
            </h2>

            {orders.length === 0 ? (
                <div className="bg-white rounded-[2rem] p-16 text-center shadow-sm border border-slate-100">
                    <div className="w-24 h-24 bg-blue-50 rounded-full flex items-center justify-center mx-auto mb-6">
                        <ShoppingBag className="w-12 h-12 text-blue-300" />
                    </div>
                    <h3 className="text-xl font-bold text-slate-800 mb-2">لا توجد طلبات جديدة</h3>
                    <p className="text-slate-400">ستظهر الطلبات هنا عندما يقوم الزبائن بالشراء.</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {/* Order list would go here */}
                </div>
            )}
          </div>
        )}

        {view === 'SETTINGS' && (
          <div className="max-w-2xl mx-auto bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 animate-fade-in-up">
             <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center gap-3">
                <Settings className="w-8 h-8 text-slate-400" /> إعدادات المتجر
              </h2>
              <div className="space-y-6">
                <div className="flex items-center gap-4 p-5 bg-blue-50/50 rounded-3xl text-blue-700 border border-blue-100">
                  <div className="bg-white p-3 rounded-xl shadow-sm"><MapPin className="w-6 h-6 text-blue-600" /></div>
                  <div>
                    <h3 className="font-bold text-lg">موقع المتجر (GPS)</h3>
                    <p className="text-xs opacity-80 font-medium mt-1">يستخدم لتحديد المسافة بينك وبين الزبائن</p>
                  </div>
                  <button className="mr-auto bg-blue-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg shadow-blue-500/30 hover:bg-blue-700">تحديث</button>
                </div>
                <div>
                   <label className="block text-sm font-bold text-slate-500 mb-2">اسم المتجر</label>
                   <input type="text" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" defaultValue={userName} />
                </div>
                 <div>
                   <label className="block text-sm font-bold text-slate-500 mb-2">ساعات العمل</label>
                   <div className="flex gap-4">
                      <div className="flex-1 relative">
                          <span className="absolute -top-2 right-3 bg-white px-1 text-[10px] font-bold text-slate-400">من</span>
                          <input type="time" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" />
                      </div>
                      <div className="flex-1 relative">
                          <span className="absolute -top-2 right-3 bg-white px-1 text-[10px] font-bold text-slate-400">إلى</span>
                          <input type="time" className="w-full p-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-700" />
                      </div>
                   </div>
                </div>
                <button className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold mt-4 hover:bg-slate-800 transition-colors">حفظ التغييرات</button>
              </div>
          </div>
        )}
      </main>
    </div>
  );
};

export enum UserRole {
  GUEST = 'GUEST',
  CUSTOMER = 'CUSTOMER',
  STORE = 'STORE',
  DRIVER = 'DRIVER'
}

export enum OrderStatus {
  PENDING = 'PENDING',               // Customer placed it, waiting for store
  ACCEPTED_BY_STORE = 'ACCEPTED_BY_STORE', // Store accepted, waiting for driver
  ACCEPTED_BY_DRIVER = 'ACCEPTED_BY_DRIVER', // Driver accepted, on the way
  DELIVERED = 'DELIVERED',           // Complete
  CANCELLED = 'CANCELLED'
}

export enum Category {
  FOOD = 'مطاعم',
  CLOTHES = 'ملابس',
  PHONES = 'هواتف وفليكسي',
  SERVICES = 'خدمات',
  KIDS = 'أطفال'
}

export interface Coordinates {
  lat: number;
  lng: number;
}

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  category: Category;
  storeId: string;
}

export interface StoreProfile {
  id: string;
  name: string;
  rating: number;
  reviewCount: number;
  isVerified: boolean;
  category: Category;
  location: string;
  coordinates: Coordinates; // For distance calculation
  image: string;
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  storeId: string;
  storeName: string;
  driverId?: string;
  driverName?: string;
  products: {product: Product, quantity: number}[];
  totalPrice: number;
  deliveryFee: number;
  status: OrderStatus;
  timestamp: number;
  address: string;
  coordinates?: Coordinates;
  storeCoordinates?: Coordinates;
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar?: string;
}

import React, { useState, useMemo, useEffect } from 'react';
import { Category, Product, StoreProfile, OrderStatus } from '../types';
import { calculateDistance, calculateDeliveryFee, formatCurrency, BIR_EL_ATER_CENTER } from '../utils/helpers';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set } from 'firebase/database';
import { Search, Star, Plus, Minus, ShoppingCart, ShoppingBag, MapPin, X, ShieldCheck, Bike, CheckCircle, ChevronLeft, Clock, ArrowRight, Loader2, Store, Utensils } from 'lucide-react';

interface CustomerScreenProps {
  onLogout: () => void;
  userName: string;
}

const USER_LOCATION = { lat: 34.7520, lng: 8.0550 };

export const CustomerScreen: React.FC<CustomerScreenProps> = ({ onLogout, userName }) => {
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [activeStoreProducts, setActiveStoreProducts] = useState<Product[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [showCart, setShowCart] = useState(false);

  // Real Order Tracking State
  const [currentOrderId, setCurrentOrderId] = useState<string | null>(null);
  const [orderStatus, setOrderStatus] = useState<OrderStatus | null>(null);

  const [showRating, setShowRating] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);

  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [loadingStores, setLoadingStores] = useState(true);

  // Handle Scroll Effect for Header
  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Fetch REAL Stores
  useEffect(() => {
    const storesRef = ref(db, 'stores');
    const unsubscribe = onValue(storesRef, (snapshot) => {
        const data = snapshot.val();
        let loadedStores: StoreProfile[] = [];

        if (data) {
            loadedStores = Object.keys(data).map(key => {
                const storeData = data[key];
                return {
                    id: key, 
                    name: storeData.name || 'متجر بدون اسم',
                    rating: 4.5,
                    reviewCount: 0,
                    isVerified: true,
                    category: Category.FOOD,
                    location: 'بئر العاتر',
                    coordinates: storeData.coordinates || { 
                        lat: BIR_EL_ATER_CENTER.lat + (Math.random() - 0.5) * 0.01, 
                        lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.01 
                    },
                    image: `https://picsum.photos/200/200?random=${key}`
                };
            });
        }

        const localStores = JSON.parse(localStorage.getItem('kimo_local_stores') || '[]');
        localStores.forEach((localStore: any) => {
            if (!loadedStores.find(s => s.id === localStore.id)) {
                loadedStores.push({
                    ...localStore,
                    coordinates: localStore.coordinates || { 
                        lat: BIR_EL_ATER_CENTER.lat + (Math.random() - 0.5) * 0.01, 
                        lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.01 
                    }
                });
            }
        });

        setStores(loadedStores);
        setLoadingStores(false);
    });
    return () => unsubscribe();
  }, []);

  // Fetch products
  useEffect(() => {
    if (activeStore) {
      setLoadingProducts(true);
      const productsRef = ref(db, 'products');

      const unsubscribe = onValue(productsRef, (snapshot) => {
        let allProducts: Product[] = [];
        const data = snapshot.val();
        if (data) {
          allProducts = Object.values(data) as Product[];
        }

        const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
        allProducts = [...allProducts, ...localProducts];

        const storeProducts = allProducts.filter((p: any) => p.storeId === activeStore.id);

        setActiveStoreProducts(storeProducts);
        setLoadingProducts(false);
      });

      return () => unsubscribe();
    } else {
      setActiveStoreProducts([]);
    }
  }, [activeStore]);

  // TRACK ORDER STATUS
  useEffect(() => {
    if (currentOrderId) {
        const orderRef = ref(db, `orders/${currentOrderId}`);
        const unsubscribe = onValue(orderRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                setOrderStatus(data.status);
            }
        });
        return () => unsubscribe();
    }
  }, [currentOrderId]);

  const storesWithDistance = useMemo(() => {
    return stores.map(store => ({
      ...store,
      distance: calculateDistance(USER_LOCATION, store.coordinates)
    })).sort((a, b) => a.distance - b.distance);
  }, [stores]);

  const filteredStores = useMemo(() => {
    let result = storesWithDistance;
    if (selectedCategory !== 'ALL') {
      result = result.filter(s => s.category === selectedCategory);
    }
    if (searchQuery) {
      result = result.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));
    }
    return result;
  }, [selectedCategory, searchQuery, storesWithDistance]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) {
        return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      }
      return [...prev, { product, quantity: 1 }];
    });
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
        if (item.product.id === productId) {
            return { ...item, quantity: Math.max(0, item.quantity + delta) };
        }
        return item;
    }).filter(item => item.quantity > 0));
  }

  const cartTotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);

  const getDeliveryDistance = () => {
      if (activeStore) return calculateDistance(USER_LOCATION, activeStore.coordinates);
      if (cart.length > 0) {
          const storeId = cart[0].product.storeId;
          const store = stores.find(s => s.id === storeId);
          return store ? calculateDistance(USER_LOCATION, store.coordinates) : 0;
      }
      return 0;
  }

  const deliveryDistance = getDeliveryDistance();
  const deliveryFee = calculateDeliveryFee(deliveryDistance, cartTotal);
  const grandTotal = cartTotal + deliveryFee;

  const handlePlaceOrder = async () => {
    if (cart.length === 0) return;

    // Determine store (assuming all items from same store for now)
    const storeId = cart[0].product.storeId;
    const store = stores.find(s => s.id === storeId);

    if (!auth.currentUser) {
        alert("يجب تسجيل الدخول لإتمام الطلب");
        return;
    }

    const orderData = {
        customerId: auth.currentUser.uid,
        customerName: userName,
        storeId: storeId,
        storeName: store?.name || 'Unknown Store',
        products: cart,
        totalPrice: grandTotal,
        deliveryFee: deliveryFee,
        status: OrderStatus.PENDING,
        timestamp: Date.now(),
        address: 'حي السلام، بئر العاتر', // Hardcoded for demo
        coordinates: USER_LOCATION,
        storeCoordinates: store?.coordinates
    };

    try {
        const newOrderRef = push(ref(db, 'orders'));
        await set(newOrderRef, orderData);

        setCurrentOrderId(newOrderRef.key);
        setOrderStatus(OrderStatus.PENDING);
        setShowCart(false);
    } catch (error) {
        console.error("Error placing order:", error);
        alert("حدث خطأ أثناء إرسال الطلب");
    }
  };

  const closeOrderFlow = () => {
    setShowRating(true);
    setCart([]);
    setActiveStore(null);
    setCurrentOrderId(null);
    setOrderStatus(null);
  };

  // ORDER TRACKING SCREEN (Dynamic based on Firebase Status)
  if (currentOrderId && orderStatus) {
    let stage = 1;
    let message = 'يتم إرسال طلبك للمتجر...';
    let icon = <Loader2 className="w-14 h-14 text-brand-500 animate-spin" />;

    if (orderStatus === OrderStatus.PENDING) {
        stage = 1;
        message = 'بانتظار موافقة المتجر...';
        icon = <Store className="w-14 h-14 text-brand-500 animate-bounce" />;
    } else if (orderStatus === OrderStatus.ACCEPTED_BY_STORE) {
        stage = 2;
        message = 'المتجر يجهز طلبك الآن! جاري البحث عن سائق...';
        icon = <Utensils className="w-14 h-14 text-orange-500 animate-pulse" />;
    } else if (orderStatus === OrderStatus.ACCEPTED_BY_DRIVER) {
