          <button 
            onClick={() => setActiveTab('AVAILABLE')}
            className={`flex-1 py-2 text-sm font-bold rounded-lg transition-colors ${activeTab === 'AVAILABLE' ? 'bg-slate-100 text-slate-800' : 'text-slate-400'}`}
