import { BIR_EL_ATER_CENTER } from '../utils/helpers';

interface AuthScreenProps {
  onLogin: (role: UserRole, name?: string) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });
  const [error, setError] = useState('');

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
    setError('');
  };

  const handleBack = () => {
    setSelectedRole(null);
    setFormData({ name: '', email: '', phone: '', password: '' });
    setError('');
  };

  const getDatabasePath = (role: UserRole) => {
    switch (role) {
      case UserRole.CUSTOMER: return 'customers';
      case UserRole.STORE: return 'stores';
      case UserRole.DRIVER: return 'drivers';
      default: return 'users';
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Basic validation
    if (!formData.email || !formData.password || (authMode === 'REGISTER' && (!formData.name || !formData.phone))) {
      setError('يرجى ملء جميع الحقول المطلوبة');
      return;
    }

    setIsLoading(true);

    try {
      if (authMode === 'REGISTER') {
        // 1. Create User in Firebase Auth
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;

        // 2. Try to Save profile in Realtime Database (Role Specific Path)
        if (selectedRole) {
          // Important: Save to LocalStorage immediately as fallback
          localStorage.setItem('kimo_user_name', formData.name);
          localStorage.setItem('kimo_user_role', selectedRole);

          // NEW: If role is STORE, save to local stores list for visibility
          if (selectedRole === UserRole.STORE) {
              const localStores = JSON.parse(localStorage.getItem('kimo_local_stores') || '[]');
              if (!localStores.find((s: any) => s.id === user.uid)) {
                  localStores.push({
                      id: user.uid,
                      name: formData.name,
                      category: 'مطاعم', // Default
                      location: 'بئر العاتر',
                      isVerified: false,
                      rating: 5,
                      reviewCount: 0,
                      image: `https://picsum.photos/200/200?random=${user.uid.slice(0,5)}`,
                      coordinates: {
                          lat: BIR_EL_ATER_CENTER.lat + (Math.random() - 0.5) * 0.005,
                          lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.005
                      }
                  });
                  localStorage.setItem('kimo_local_stores', JSON.stringify(localStores));
              }
          }

          const dbPath = getDatabasePath(selectedRole);

          try {
            await set(ref(db, `${dbPath}/${user.uid}`), {
              name: formData.name,
              email: formData.email,
              phone: formData.phone,
              role: selectedRole,
              createdAt: Date.now()
            });
          } catch (dbError) {
            console.warn("Database write failed (likely permissions), continuing with Local Storage.");
          }

          // Always succeed locally
          onLogin(selectedRole, formData.name);
        }

      } else {
        // Login Logic
        await signInWithEmailAndPassword(auth, formData.email, formData.password);

        // On Login, we don't have the name in formData usually (unless user typed it unnecessarily)
        // App.tsx will handle fetching the name from DB/Storage via onAuthStateChanged
        // But if user specifically selected a role before login, we pass it to optimize UX
        if (selectedRole) {
            // Note: App.tsx will verify if this role is correct against DB
            onLogin(selectedRole);
        }
      }
    } catch (err: any) {
      let message = "حدث خطأ غير متوقع";

      // Handle Authentication Errors
      switch (err.code) {
        case 'auth/invalid-credential':
        case 'auth/user-not-found':
        case 'auth/wrong-password':
          message = "البريد الإلكتروني أو كلمة المرور غير صحيحة";
          break;
        case 'auth/email-already-in-use':
          message = "البريد الإلكتروني مستخدم بالفعل";
          break;
        case 'auth/invalid-email':
          message = "البريد الإلكتروني غير صالح";
          break;
        case 'auth/weak-password':
          message = "كلمة المرور ضعيفة جداً";
          break;
        case 'auth/network-request-failed':
            message = "تحقق من اتصالك بالإنترنت";
            break;
        default:
          console.error("Auth Error:", err); 
          message = `حدث خطأ: ${err.message}`;
      }

      setError(message);
    } finally {
      setIsLoading(false);
    }
  };

  // ----------------------------------------------------
