        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl px-4 z-10">
          <RoleCard 
            icon={<ShoppingBag className="w-9 h-9" />}
            title="أنا زبون"
            desc="تصفح واطلب من المتاجر"
            theme="blue"
