                        lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.01 
                    },
                    image: `https://picsum.photos/200/200?random=${key}`
                };
            });
        }

        const localStores = JSON.parse(localStorage.getItem('kimo_local_stores') || '[]');
        localStores.forEach((localStore: any) => {
            if (!loadedStores.find(s => s.id === localStore.id)) {
                loadedStores.push({
                    ...localStore,
                    coordinates: localStore.coordinates || { 
                        lat: BIR_EL_ATER_CENTER.lat + (Math.random() - 0.5) * 0.01, 
                        lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.01 
                    }
                });
            }
        });

        setStores(loadedStores);
        setLoadingStores(false);
    });
    return () => unsubscribe();
  }, []);

  // Fetch products
  useEffect(() => {
    if (activeStore) {
      setLoadingProducts(true);
      const productsRef = ref(db, 'products');

      const unsubscribe = onValue(productsRef, (snapshot) => {
        let allProducts: Product[] = [];
        const data = snapshot.val();
        if (data) {
          allProducts = Object.values(data) as Product[];
        }

        const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
        allProducts = [...allProducts, ...localProducts];

        const storeProducts = allProducts.filter((p: any) => p.storeId === activeStore.id);

        setActiveStoreProducts(storeProducts);
        setLoadingProducts(false);
      });

      return () => unsubscribe();
    } else {
      setActiveStoreProducts([]);
    }
  }, [activeStore]);

  // TRACK ORDER STATUS
  useEffect(() => {
    if (currentOrderId) {
        const orderRef = ref(db, `orders/${currentOrderId}`);
        const unsubscribe = onValue(orderRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                setOrderStatus(data.status);
            }
        });
        return () => unsubscribe();
    }
  }, [currentOrderId]);

  const storesWithDistance = useMemo(() => {
    return stores.map(store => ({
      ...store,
      distance: calculateDistance(USER_LOCATION, store.coordinates)
    })).sort((a, b) => a.distance - b.distance);
  }, [stores]);

  const filteredStores = useMemo(() => {
    let result = storesWithDistance;
    if (selectedCategory !== 'ALL') {
      result = result.filter(s => s.category === selectedCategory);
    }
    if (searchQuery) {
      result = result.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));
    }
    return result;
  }, [selectedCategory, searchQuery, storesWithDistance]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) {
        return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      }
      return [...prev, { product, quantity: 1 }];
    });
  };

  const updateQuantity = (productId: string, delta: number) => {
    setCart(prev => prev.map(item => {
        if (item.product.id === productId) {
            return { ...item, quantity: Math.max(0, item.quantity + delta) };
        }
        return item;
    }).filter(item => item.quantity > 0));
  }

  const cartTotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);

  const getDeliveryDistance = () => {
      if (activeStore) return calculateDistance(USER_LOCATION, activeStore.coordinates);
      if (cart.length > 0) {
          const storeId = cart[0].product.storeId;
          const store = stores.find(s => s.id === storeId);
          return store ? calculateDistance(USER_LOCATION, store.coordinates) : 0;
      }
      return 0;
  }

  const deliveryDistance = getDeliveryDistance();
  const deliveryFee = calculateDeliveryFee(deliveryDistance, cartTotal);
  const grandTotal = cartTotal + deliveryFee;

  const handlePlaceOrder = async () => {
    if (cart.length === 0) return;

    // Determine store (assuming all items from same store for now)
    const storeId = cart[0].product.storeId;
    const store = stores.find(s => s.id === storeId);

    if (!auth.currentUser) {
        alert("يجب تسجيل الدخول لإتمام الطلب");
        return;
    }

    const orderData = {
        customerId: auth.currentUser.uid,
        customerName: userName,
        storeId: storeId,
        storeName: store?.name || 'Unknown Store',
        products: cart,
        totalPrice: grandTotal,
        deliveryFee: deliveryFee,
        status: OrderStatus.PENDING,
        timestamp: Date.now(),
        address: 'حي السلام، بئر العاتر', // Hardcoded for demo
        coordinates: USER_LOCATION,
        storeCoordinates: store?.coordinates
    };

    try {
        const newOrderRef = push(ref(db, 'orders'));
        await set(newOrderRef, orderData);

        setCurrentOrderId(newOrderRef.key);
        setOrderStatus(OrderStatus.PENDING);
        setShowCart(false);
    } catch (error) {
        console.error("Error placing order:", error);
        alert("حدث خطأ أثناء إرسال الطلب");
    }
  };

  const closeOrderFlow = () => {
    setShowRating(true);
    setCart([]);
    setActiveStore(null);
    setCurrentOrderId(null);
    setOrderStatus(null);
  };

  // ORDER TRACKING SCREEN (Dynamic based on Firebase Status)
  if (currentOrderId && orderStatus) {
    let stage = 1;
    let message = 'يتم إرسال طلبك للمتجر...';
    let icon = <Loader2 className="w-14 h-14 text-brand-500 animate-spin" />;
    let progressBarColor = 'from-brand-500 to-brand-400';
    let iconBgColor = 'bg-brand-100';

    if (orderStatus === OrderStatus.PENDING) {
        stage = 1;
        message = 'بانتظار موافقة المتجر...';
        icon = <Store className="w-14 h-14 text-brand-500 animate-bounce-small" />;
        progressBarColor = 'from-brand-500 to-brand-400';
        iconBgColor = 'bg-brand-100';
    } else if (orderStatus === OrderStatus.ACCEPTED_BY_STORE) {
        stage = 2;
        message = 'المتجر يجهز طلبك الآن! جاري البحث عن سائق...';
        icon = <Utensils className="w-14 h-14 text-warning animate-pulse" />;
        progressBarColor = 'from-warning to-orange-400';
        iconBgColor = 'bg-warning/20';
    } else if (orderStatus === OrderStatus.ACCEPTED_BY_DRIVER) {
        stage = 3;
        message = 'السائق في الطريق إليك!';
        icon = <Bike className="w-14 h-14 text-blue-500 animate-float" />;
        progressBarColor = 'from-blue-500 to-blue-400';
        iconBgColor = 'bg-blue-100';
    } else if (orderStatus === OrderStatus.DELIVERED) {
        stage = 4;
        message = 'وصل الطلب! بالصحة والعافية.';
        icon = <CheckCircle className="w-14 h-14 text-success" />;
        progressBarColor = 'from-success to-emerald-400';
        iconBgColor = 'bg-success/20';
    }

    // Determine progress bar width
    const progressWidth = stage === 1 ? '25%' : stage === 2 ? '50%' : stage === 3 ? '75%' : '100%';

    return (
      <div className="min-h-screen bg-primary-50 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-b from-primary-50 to-white opacity-50 z-0"></div>

        <div className="w-full max-w-md bg-white/90 backdrop-blur-xl rounded-4xl p-10 shadow-2xl border border-white/50 z-10 text-center animate-scale-up">
           <div className="relative mb-8 mx-auto w-36 h-36">
             <div className={`absolute inset-0 ${iconBgColor} rounded-full animate-pulse-slow opacity-50`}></div>
             <div className="relative bg-white w-36 h-36 rounded-full flex items-center justify-center shadow-lg border-4 border-primary-50">
               {icon}
             </div>
           </div>

           <h2 className="text-4xl font-black text-primary-800 mb-3 font-cairo">
            {stage === 4 ? 'تم التوصيل' : 'حالة الطلب'}
          </h2>

          <p className="text-primary-600 mb-8 font-medium leading-relaxed text-lg">
            {message}
          </p>

          <div className="w-full bg-primary-100 rounded-full h-3 mb-8 overflow-hidden">
             <div 
                className={`h-full bg-gradient-to-r ${progressBarColor} rounded-full transition-all duration-1000 ease-out shadow-[0_0_10px_rgba(249,115,22,0.5)]`} 
                style={{ width: progressWidth }}
             ></div>
          </div>

          {stage === 4 && (
            <button onClick={closeOrderFlow} className="w-full bg-primary-900 text-white py-4 rounded-3xl font-bold shadow-xl hover:scale-105 transition-transform hover:bg-brand-600">
              إتمام وتقييم
            </button>
          )}

          {stage < 4 && (
              <p className="text-xs text-primary-400 mt-4">رقم الطلب: {currentOrderId.slice(-6)}</p>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="bg-primary-50 min-h-screen pb-28">
      {showRating && <RatingModal type="STORE" targetName={activeStore?.name || "المتجر"} onClose={() => setShowRating(false)} />}

      {/* Floating Header */}
      <header className={`fixed top-0 left-0 right-0 z-40 transition-all duration-300 ${scrolled ? 'glass shadow-lg py-2' : 'bg-transparent py-4'}`}>
        <div className="container max-w-lg mx-auto px-4 flex items-center justify-between">
          {!activeStore ? (
             <div className="flex items-center gap-3">
               <div className="w-10 h-10 bg-brand-600 rounded-2xl flex items-center justify-center shadow-lg shadow-brand-500/30">
                 <span className="text-white font-black text-xl">K</span>
               </div>
               <div className={`transition-all duration-300 ${scrolled ? 'opacity-0 w-0 overflow-hidden' : 'opacity-100'}`}>
                 <h1 className="font-bold text-primary-800 text-lg leading-none">مرحباً، {userName || 'زائر'}</h1>
                 <p className="text-xs text-primary-500 flex items-center mt-1">
                   <MapPin className="w-3 h-3 ml-1 text-brand-500" /> حي السلام، بئر العاتر
                 </p>
               </div>
             </div>
          ) : (
             <button onClick={() => setActiveStore(null)} className="flex items-center gap-2 glass px-3 py-2 rounded-3xl backdrop-blur-md border border-white/50 hover:bg-white/70">
                <ChevronLeft className="w-5 h-5 text-primary-700" />
                <span className="font-bold text-primary-700">العودة</span>
             </button>
          )}

          <div className="flex items-center gap-2">
            {!activeStore && (
                <button onClick={onLogout} className="w-11 h-11 glass rounded-full flex items-center justify-center text-primary-400 hover:text-danger shadow-sm border border-white/50">
                    <X className="w-5 h-5" />
                </button>
            )}
            {activeStore && (
              <button 
                  className="relative w-12 h-12 bg-primary-900 rounded-full flex items-center justify-center shadow-lg hover:bg-brand-600 transition-colors"
                  onClick={() => setShowCart(true)}
              >
                  <ShoppingCart className="w-6 h-6 text-white" />
                  {cart.length > 0 && (
                  <span className="absolute -top-1 -right-1 bg-danger text-white text-[10px] w-5 h-5 rounded-full flex items-center justify-center border-2 border-white font-bold animate-scale-up">
                      {cart.length}
                  </span>
                  )}
              </button>
            )}
          </div>
        </div>
      </header>

      {/* MAIN CONTENT */}
      <div className="container max-w-lg mx-auto pt-24 px-4">

        {!activeStore ? (
          <div className="space-y-8 animate-fade-in-up">

            {/* Search Bar */}
            <div className="relative group">
               <input 
                  type="text" 
                  placeholder="ابحث عن مطعم، أكلة، أو متجر..." 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-white border border-primary-100 rounded-3xl py-4 pl-4 pr-12 shadow-md text-primary-700 font-bold focus:ring-2 focus:ring-brand-500 focus:shadow-lg focus:border-brand-300 transition-all placeholder:font-normal placeholder:text-primary-400"
               />
               <Search className="absolute right-4 top-4 w-6 h-6 text-primary-400 group-focus-within:text-brand-500 transition-colors" />
            </div>

            {/* Map Snippet */}
            <div className="bg-white p-2 rounded-4xl shadow-md border border-primary-100 overflow-hidden">
                <div className="flex justify-between items-center px-4 py-2">
                   <h2 className="font-bold text-primary-800">بالقرب منك</h2>
                   <span className="text-xs text-brand-600 font-bold bg-brand-50 px-2 py-1 rounded-xl cursor-pointer hover:bg-brand-100">عرض الخريطة الكاملة</span>
                </div>
                <div className="rounded-3xl overflow-hidden">
                   <MapVisualizer userType="CUSTOMER" height="h-32" />
                </div>
            </div>

            {/* Categories - Horizontal Scroll */}
            <div>
              <div className="flex items-center justify-between mb-4">
                 <h2 className="font-bold text-xl text-primary-800">الأقسام</h2>
              </div>
              <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide snap-x">
                {['ALL', ...Object.values(Category)].map((cat, idx) => (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat as Category | 'ALL')}
                    className={`snap-start shrink-0 px-6 py-3 rounded-3xl whitespace-nowrap text-sm font-bold transition-all duration-300 ${
                      selectedCategory === cat 
                      ? 'bg-primary-900 text-white shadow-lg shadow-primary-900/20 scale-105' 
                      : 'bg-white text-primary-600 border border-primary-100 hover:border-brand-200 hover:text-brand-600'
                    }`}
                  >
                    {cat === 'ALL' ? 'الكل' : cat}
                  </button>
                ))}
              </div>
            </div>

            {/* Stores Grid */}
            <div className="space-y-4">
                <h2 className="font-bold text-xl text-primary-800">المتاجر المتاحة</h2>

                {loadingStores ? (
                    <div className="flex justify-center items-center h-40">
                         <Loader2 className="w-8 h-8 text-brand-500 animate-spin" />
                    </div>
                ) : filteredStores.length === 0 ? (
                    <div className="text-center py-10 bg-white rounded-4xl border border-dashed border-primary-200">
                        <Store className="w-12 h-12 text-primary-300 mx-auto mb-2" />
                        <p className="text-primary-500 font-bold">لا توجد متاجر مسجلة حالياً</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 gap-6 pb-4">
                        {filteredStores.map((store, idx) => (
                        <div 
                            key={store.id} 
                            onClick={() => setActiveStore(store)}
                            className="bg-white rounded-4xl overflow-hidden shadow-md hover:shadow-xl transition-all duration-300 cursor-pointer group border border-primary-100"
                        >
                            <div className="h-44 bg-primary-200 relative overflow-hidden">
                                <img src={store.image} alt={store.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                <div className="absolute inset-0 bg-gradient-to-t from-primary-900/80 via-transparent to-transparent opacity-60"></div>

                                {/* Floating Badges */}
                                <div className="absolute top-4 right-4 flex gap-2">
                                    {store.isVerified && (
                                        <div className="bg-blue-500/90 backdrop-blur-sm text-white p-2 rounded-full shadow-md">
                                            <ShieldCheck className="w-4 h-4" />
                                        </div>
                                    )}
                                </div>
                                <div className="absolute bottom-4 right-4 text-white">
                                    <h3 className="font-bold text-2xl leading-none mb-1">{store.name}</h3>
                                    <p className="text-xs opacity-80 font-light flex items-center gap-1">
                                        <MapPin className="w-3 h-3" /> {store.location}
                                    </p>
                                </div>
                                <div className="absolute bottom-4 left-4 glass bg-white/20 backdrop-blur-md border border-white/30 text-white px-3 py-1.5 rounded-2xl text-xs font-bold flex items-center gap-1">
                                    <Star className="w-3 h-3 text-warning fill-warning" /> {store.rating}
                                </div>
                            </div>

                            <div className="p-5 flex justify-between items-center">
                                <div className="flex gap-3">
                                    <div className="bg-primary-50 px-3 py-1.5 rounded-2xl text-xs font-bold text-primary-500 border border-primary-100">
                                        {store.category}
                                    </div>
                                    <div className="bg-brand-50 px-3 py-1.5 rounded-2xl text-xs font-bold text-brand-600 flex items-center gap-1">
                                        <Clock className="w-3 h-3" /> 25 دقيقة
                                    </div>
                                </div>
                                <span className="text-sm font-bold text-primary-900">{store.distance} كم</span>
                            </div>
                        </div>
                        ))}
                    </div>
                )}
            </div>
          </div>
        ) : (
          // STORE DETAIL VIEW
          <div className="animate-fade-in-up pb-10">
            {/* Store Hero */}
            <div className="relative h-64 rounded-4xl overflow-hidden shadow-lg mb-8 group">
                <img src={activeStore.image} alt={activeStore.name} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-primary-900/80 via-primary-900/20 to-transparent"></div>
                <div className="absolute bottom-6 right-6 text-white z-10">
                    <h2 className="text-4xl font-black mb-2">{activeStore.name}</h2>
                    <div className="flex items-center gap-4 text-sm font-medium opacity-90">
                         <span className="flex items-center gap-1"><Star className="w-4 h-4 text-warning fill-current" /> {activeStore.rating} ({activeStore.reviewCount} تقييم)</span>
                         <span className="w-1 h-1 bg-white rounded-full"></span>
                         <span>{activeStore.category}</span>
                    </div>
                </div>
            </div>

            <div className="flex items-center justify-between mb-6">
                 <h3 className="font-bold text-xl text-primary-800">المنتجات</h3>
            </div>

            {/* Products List */}
            <div className="space-y-4">
              {loadingProducts ? (
                <div className="flex justify-center items-center py-20">
                    <Loader2 className="w-8 h-8 text-brand-500 animate-spin" />
                </div>
              ) : activeStoreProducts.length > 0 ? (
                activeStoreProducts.map((product, idx) => (
                    <div key={product.id} 
                        className="bg-white p-4 rounded-3xl shadow-md border border-primary-50 flex gap-4 transition-all hover:shadow-lg hover:-translate-y-1 group"
                        style={{ animationDelay: `${idx * 50}ms` }}
                    >
                    <div className="w-28 h-28 shrink-0 rounded-2xl overflow-hidden bg-primary-100">
                        <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    </div>
                    <div className="flex-1 flex flex-col justify-between py-1">
                        <div>
                        <h3 className="font-bold text-lg text-primary-800 leading-tight mb-1">{product.name}</h3>
                        <p className="text-xs text-primary-500 line-clamp-2 leading-relaxed">{product.description}</p>
                        </div>
                        <div className="flex justify-between items-end mt-2">
                        <span className="font-black text-xl text-brand-600">{formatCurrency(product.price)}</span>
                        <button 
                            onClick={(e) => { e.stopPropagation(); addToCart(product); }}
                            className="bg-primary-900 text-white w-10 h-10 rounded-full hover:bg-brand-600 transition-colors shadow-lg shadow-primary-900/20 flex items-center justify-center active:scale-90"
                        >
                            <Plus className="w-5 h-5" />
                        </button>
                        </div>
                    </div>
                    </div>
                ))
              ) : (
                <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-primary-300">
                    <ShoppingBag className="w-12 h-12 text-primary-300 mx-auto mb-3" />
                    <p className="text-primary-400 font-medium">لا توجد منتجات حالياً لهذا المتجر</p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Modern Cart Bottom Sheet */}
      {showCart && (
        <>
            <div className="fixed inset-0 bg-primary-900/60 z-50 backdrop-blur-sm transition-opacity" onClick={() => setShowCart(false)}></div>
            <div className="fixed bottom-0 left-0 right-0 z-[60] bg-white rounded-t-5xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] max-h-[85vh] flex flex-col animate-slide-up">

                {/* Drag Handle */}
                <div className="w-full flex justify-center pt-4 pb-2" onClick={() => setShowCart(false)}>
                    <div className="w-12 h-1.5 bg-primary-200 rounded-full"></div>
                </div>

                <div className="p-6 flex-1 overflow-y-auto">
                    <div className="flex justify-between items-center mb-6">
                         <h2 className="text-2xl font-black text-primary-800">سلة المشتريات</h2>
                         <span className="bg-brand-100 text-brand-700 font-bold px-3 py-1 rounded-2xl text-sm">{cart.length} منتجات</span>
                    </div>

                    {cart.length === 0 ? (
                        <div className="text-center py-10 opacity-50">
                            <ShoppingCart className="w-16 h-16 mx-auto mb-4 text-primary-400" />
                            <p className="text-primary-500">سلتك فارغة</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {cart.map((item) => (
                                <div key={item.product.id} className="flex items-center gap-4 bg-primary-50 p-3 rounded-3xl">
                                    <img src={item.product.image} className="w-16 h-16 rounded-2xl object-cover" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-primary-800">{item.product.name}</h4>
                                        <div className="flex items-center gap-1 text-brand-600 font-bold text-sm">
                                            {formatCurrency(item.product.price)}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 bg-white px-2 py-1 rounded-2xl shadow-sm border border-primary-100">
                                        <button onClick={() => updateQuantity(item.product.id, -1)} className="p-1 text-primary-500 hover:text-danger"><Minus className="w-4 h-4"/></button>
                                        <span className="font-bold text-sm w-4 text-center text-primary-700">{item.quantity}</span>
                                        <button onClick={() => updateQuantity(item.product.id, 1)} className="p-1 text-primary-500 hover:text-success"><Plus className="w-4 h-4"/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {cart.length > 0 && (
                    <div className="p-6 bg-primary-50 border-t border-primary-100 pb-8">
                        <div className="space-y-2 mb-6 text-sm font-medium text-primary-600">
                             <div className="flex justify-between"><span>المجموع</span> <span className="text-primary-800">{formatCurrency(cartTotal)}</span></div>
                             <div className="flex justify-between"><span>التوصيل</span> <span className="text-brand-600">{formatCurrency(deliveryFee)}</span></div>
                             <div className="flex justify-between text-lg font-black text-primary-900 pt-2 border-t border-primary-200 mt-2">
                                <span>الإجمالي</span> <span>{formatCurrency(grandTotal)}</span>
                             </div>
                        </div>
                        <button 
                            onClick={handlePlaceOrder}
                            className="w-full bg-primary-900 text-white py-4 rounded-3xl font-bold text-lg hover:bg-brand-600 transition-colors shadow-xl shadow-primary-900/20 flex items-center justify-center gap-2 group"
                        >
                            <span>تأكيد الطلب</span>
                            <ArrowRight className="w-5 h-5 group-hover:translate-x-[-4px] transition-transform" />
                        </button>
                    </div>
                )}
            </div>
        </>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Category, Product, Order, OrderStatus } from '../types';
import { generateProductDescription } from '../services/geminiService';
import { db, auth } from '../services/firebase';
import { ref, push, set, onValue, remove, update } from 'firebase/database';
import { Sparkles, Package, Plus, Settings, MapPin, Store as StoreIcon, ChevronRight, Upload, X, Loader2, Trash2, Edit, ArrowLeft, ClipboardList, ShoppingBag, CheckCircle, Clock } from 'lucide-react';
import CryptoJS from 'crypto-js';
import { BIR_EL_ATER_CENTER, formatCurrency } from '../utils/helpers';

interface StoreScreenProps {
  onLogout: () => void;
  userName: string;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({ onLogout, userName }) => {
  const [view, setView] = useState<'PRODUCTS' | 'ORDERS' | 'SETTINGS'>('PRODUCTS');

  // State for managing products list
  const [myProducts, setMyProducts] = useState<Product[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(true);

  // Orders State
  const [orders, setOrders] = useState<Order[]>([]);
  const [loadingOrders, setLoadingOrders] = useState(false);

  // Toggle between List and Add Form within Products view
  const [isAddingProduct, setIsAddingProduct] = useState(false);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '',
    description: '',
    price: 0,
    category: Category.FOOD,
    image: ''
  });

  // Get current user ID
  const currentStoreId = auth.currentUser?.uid;

  // Self-Healing
  useEffect(() => {
    if (currentStoreId && userName) {
        const localStores = JSON.parse(localStorage.getItem('kimo_local_stores') || '[]');
        const exists = localStores.find((s: any) => s.id === currentStoreId);

        if (!exists) {
            localStores.push({
                id: currentStoreId,
                name: userName,
                category: Category.FOOD,
                location: 'بئر العاتر',
                isVerified: true,
                rating: 5,
                reviewCount: 0,
                image: `https://picsum.photos/200/200?random=${currentStoreId.slice(0,4)}`,
                coordinates: {
                    lat: BIR_EL_ATER_CENTER.lat + (Math.random() - 0.5) * 0.005,
                    lng: BIR_EL_ATER_CENTER.lng + (Math.random() - 0.5) * 0.005
                }
            });
            localStorage.setItem('kimo_local_stores', JSON.stringify(localStores));
        }
    }
  }, [currentStoreId, userName]);

  // Listen to Products
  useEffect(() => {
    if (!currentStoreId) return;

    const productsRef = ref(db, 'products');

    const unsubscribe = onValue(productsRef, (snapshot) => {
      const dbProducts: Product[] = [];
      const data = snapshot.val();
      if (data) {
        dbProducts.push(...(Object.values(data) as Product[]));
      }

      const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
      const allProducts = [...dbProducts, ...localProducts].filter((p: any) => p.storeId === currentStoreId);

      setMyProducts(allProducts.reverse());
      setLoadingProducts(false);
    });

    return () => unsubscribe();
  }, [currentStoreId]);

  // Listen to Orders (Realtime)
  useEffect(() => {
      if(!currentStoreId) return;

      setLoadingOrders(true);
      const ordersRef = ref(db, 'orders');

      const unsubscribe = onValue(ordersRef, (snapshot) => {
          const data = snapshot.val();
          const storeOrders: Order[] = [];

          if (data) {
              Object.keys(data).forEach(key => {
                  const order = { ...data[key], id: key };
                  // Filter by my store ID
                  if (order.storeId === currentStoreId) {
                      storeOrders.push(order);
                  }
              });
          }

          // Sort by time (newest first)
          storeOrders.sort((a, b) => b.timestamp - a.timestamp);
          setOrders(storeOrders);
          setLoadingOrders(false);
      });

      return () => unsubscribe();
  }, [currentStoreId]);

  // Accept Order Logic
  const handleAcceptOrder = async (orderId: string) => {
      try {
          await update(ref(db, `orders/${orderId}`), {
              status: OrderStatus.ACCEPTED_BY_STORE
          });
          alert("تم قبول الطلب! جاري انتظار السائق.");
      } catch (error) {
          console.error("Error accepting order:", error);
          alert("فشل قبول الطلب");
      }
  };

  const handleAIHelp = async () => {
    if (!newProduct.name || !newProduct.category) {
      alert("الرجاء إدخال اسم المنتج وتصنيفه أولاً.");
      return;
    }
    setIsGenerating(true);
    const desc = await generateProductDescription(newProduct.name, newProduct.category);
    setNewProduct(prev => ({ ...prev, description: desc }));
    setIsGenerating(false);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
          setNewProduct(prev => ({ ...prev, image: reader.result as string }));
        };
        reader.readAsDataURL(file);

        setIsUploading(true);
        try {
            const cloudName = 'dkqxgwjnr';
            const apiKey = '486896193791285';
            const apiSecret = 'gB5nJivH0GpZQ5jyXcrQ3QhPLSw';

            const timestamp = Math.round((new Date()).getTime() / 1000);
            const signature = CryptoJS.SHA1(`timestamp=${timestamp}${apiSecret}`).toString();

            const formData = new FormData();
            formData.append('file', file);
            formData.append('api_key', apiKey);
            formData.append('timestamp', timestamp.toString());
            formData.append('signature', signature);

            const response = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
                method: 'POST',
                body: formData
            });

            const data = await response.json();
            if (data.secure_url) {
                setNewProduct(prev => ({ ...prev, image: data.secure_url }));
            } else {
                alert('فشل رفع الصورة: ' + (data.error?.message || 'خطأ غير معروف'));
            }
        } catch (error) {
            console.error('Error uploading image:', error);
            alert('حدث خطأ أثناء الاتصال بالخادم. سيتم استخدام الصورة المحلية مؤقتاً.');
        } finally {
            setIsUploading(false);
        }
    }
  };

  const saveProduct = async () => {
    if (!newProduct.name || !newProduct.price || !newProduct.image) {
      alert("يرجى إكمال بيانات المنتج والصورة");
      return;
    }

    if (!currentStoreId) {
        alert("خطأ في المصادقة: يجب تسجيل الدخول كمتجر.");
        return;
    }

    setIsSaving(true);

    // Generate ID locally first to use in fallback if needed
    const tempId = `prod_${Date.now()}`; 

    const productData: Product = {
      id: tempId, // Will be overwritten if DB write succeeds with push key
      name: newProduct.name!,
      description: newProduct.description || '',
      price: newProduct.price!,
      category: newProduct.category || Category.FOOD,
      image: newProduct.image!,
      storeId: currentStoreId // Use REAL Auth UID
    };

    try {
      // Try Create a reference for the new product in Firebase
      const newProductRef = push(ref(db, 'products'));
      const dbId = newProductRef.key;

      if (dbId) {
          productData.id = dbId;
          await set(newProductRef, productData);
          alert("تم حفظ المنتج في قاعدة البيانات بنجاح!");
      } else {
          throw new Error("Could not generate DB ID");
      }

    } catch (error: any) {
      console.warn("Firebase write failed (Permission denied?), saving locally.", error);

      // Fallback: Save to LocalStorage
      const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
      localProducts.push(productData);
      localStorage.setItem('kimo_local_products', JSON.stringify(localProducts));

      // Update State Manually since onValue won't trigger for local storage
      setMyProducts(prev => [productData, ...prev]);

      alert("تم حفظ المنتج محلياً (تنبيه: لم يتم الحفظ في السيرفر بسبب الصلاحيات)");
    } finally {
      setIsSaving(false);
      setIsAddingProduct(false);
      setNewProduct({ name: '', description: '', price: 0, category: Category.FOOD, image: '' });
    }
  };

  const deleteProduct = async (id: string) => {
    if (confirm('هل أنت متأكد من حذف هذا المنتج؟')) {
      // 1. Try deleting from Firebase
      try {
        await remove(ref(db, `products/${id}`));
      } catch (error) {
        console.warn("Firebase delete failed, trying local delete.");
      }

      // 2. Always delete from LocalStorage as well (covers fallback products)
      const localProducts = JSON.parse(localStorage.getItem('kimo_local_products') || '[]');
      const updatedLocal = localProducts.filter((p: any) => p.id !== id);
      localStorage.setItem('kimo_local_products', JSON.stringify(updatedLocal));

      // 3. Update UI
      setMyProducts(prev => prev.filter(p => p.id !== id));
    }
  };

  const triggerFileInput = () => {
    fileInputRef.current?.click();
  };

  const removeImage = () => {
    setNewProduct(prev => ({ ...prev, image: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const NavItem = ({ icon, label, id, badge }: any) => (
    <button 
      onClick={() => { setView(id); setIsAddingProduct(false); }}
      className={`w-full flex items-center justify-between p-4 rounded-3xl transition-all duration-300 group ${
        view === id 
        ? 'bg-brand-600 text-white shadow-lg shadow-brand-500/30' 
        : 'hover:bg-primary-800 text-primary-300 hover:text-white'
      }`}
    >
      <div className="flex items-center gap-3">
        {icon}
        <span className="font-bold">{label}</span>
      </div>
      <div className="flex items-center gap-2">
        {badge && <span className="bg-danger text-white text-xs font-bold px-2 py-0.5 rounded-full">{badge}</span>}
        {view === id && <ChevronRight className="w-4 h-4" />}
      </div>
    </button>
  );

  return (
    <div className="min-h-screen flex bg-primary-50 overflow-hidden">
      {/* Sidebar - Premium Dark */}
      <aside className="w-72 bg-primary-900 text-white hidden md:flex flex-col p-6 m-4 rounded-5xl shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-40 h-40 bg-brand-500/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>

        <div className="text-2xl font-black mb-12 flex items-center gap-3 text-white font-cairo z-10 px-2">
           <div className="w-10 h-10 bg-brand-600 rounded-2xl flex items-center justify-center">
             <StoreIcon className="w-6 h-6 text-white" />
           </div>
           <span>كيمو <span className="text-brand-500">بيزنس</span></span>
        </div>

        <nav className="space-y-3 flex-1 z-10">
          <NavItem id="PRODUCTS" label="المنتجات" icon={<Package className="w-5 h-5" />} />
          <NavItem id="ORDERS" label="الطلبات" icon={<ClipboardList className="w-5 h-5" />} badge={orders.filter(o => o.status === 'PENDING').length || undefined} />
          <NavItem id="SETTINGS" label="الإعدادات" icon={<Settings className="w-5 h-5" />} />
        </nav>

        <div className="mt-auto border-t border-primary-800 pt-6">
           <div className="flex items-center gap-3 mb-4 px-2">
             <img src="https://picsum.photos/100" className="w-10 h-10 rounded-full border-2 border-primary-700" />
             <div>
               <p className="text-sm font-bold text-white">{userName || 'اسم المتجر'}</p>
               <p className="text-xs text-primary-500">متجر موثوق</p>
             </div>
           </div>
           <button onClick={onLogout} className="w-full py-3 bg-danger/10 text-danger rounded-2xl font-bold hover:bg-danger hover:text-white transition-colors">
              تسجيل خروج
           </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-4 md:p-8 overflow-y-auto h-screen">
        <header className="flex justify-between items-center mb-8 md:hidden">
           <h1 className="text-2xl font-black text-primary-800">إدارة المتجر</h1>
           <button onClick={onLogout} className="text-sm font-bold text-danger bg-danger/10 px-3 py-1 rounded-lg">خروج</button>
        </header>

        {view === 'PRODUCTS' && (
          <div className="max-w-4xl mx-auto animate-fade-in-up pb-10">
            {!isAddingProduct ? (
                // LIST VIEW
                <>
                    <div className="flex justify-between items-center mb-8">
                        <div>
                            <h2 className="text-2xl font-black text-primary-800">منتجاتي</h2>
                            <p className="text-primary-500 text-sm">
                              {loadingProducts ? 'جاري التحميل...' : `لديك ${myProducts.length} منتجات معروضة للبيع`}
                            </p>
                        </div>
                        <button 
                            onClick={() => setIsAddingProduct(true)}
                            className="bg-primary-900 text-white px-6 py-3 rounded-3xl font-bold flex items-center gap-2 hover:bg-brand-600 transition-colors shadow-lg"
                        >
                            <Plus className="w-5 h-5" /> إضافة منتج
                        </button>
                    </div>

                    {loadingProducts ? (
                      <div className="flex justify-center items-center h-64">
                        <Loader2 className="w-10 h-10 text-brand-500 animate-spin" />
                      </div>
                    ) : myProducts.length === 0 ? (
                        <div className="bg-white rounded-4xl p-12 text-center border border-dashed border-primary-300">
                            <div className="w-20 h-20 bg-primary-50 rounded-full flex items-center justify-center mx-auto mb-4">
                                <Package className="w-10 h-10 text-primary-300" />
                            </div>
                            <h3 className="text-xl font-bold text-primary-700 mb-2">لا توجد منتجات</h3>
                            <p className="text-primary-400 mb-6">ابدأ بإضافة منتجاتك لكي يراها الزبائن</p>
                            <button 
                                onClick={() => setIsAddingProduct(true)}
                                className="bg-brand-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-brand-700 transition-colors"
                            >
                                إضافة أول منتج
                            </button>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {myProducts.map(product => (
                                <div key={product.id} className="bg-white p-4 rounded-4xl shadow-sm border border-primary-100 flex gap-4 group hover:shadow-lg transition-all">
                                    <div className="w-32 h-32 rounded-3xl overflow-hidden relative shrink-0">
                                        <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                                        <div className="absolute top-2 right-2 bg-primary-900/60 backdrop-blur-md text-white text-[10px] px-2 py-1 rounded-lg font-bold">
                                            {product.category}
                                        </div>
                                    </div>
                                    <div className="flex-1 flex flex-col justify-between py-1">
                                        <div>
                                            <h3 className="font-bold text-lg text-primary-800">{product.name}</h3>
                                            <p className="text-xs text-primary-400 font-medium line-clamp-1">{product.description}</p>
                                        </div>
                                        <div className="flex items-end justify-between">
                                            <span className="text-xl font-black text-brand-600">{formatCurrency(product.price)}</span>
                                            <div className="flex gap-2">
                                                <button className="p-2 bg-primary-50 text-primary-400 rounded-xl hover:bg-blue-50 hover:text-blue-600 transition-colors">
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                <button 
                                                    onClick={() => deleteProduct(product.id)}
                                                    className="p-2 bg-primary-50 text-primary-400 rounded-xl hover:bg-danger/10 hover:text-danger transition-colors"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </>
            ) : (
                // ADD FORM VIEW
                <div className="bg-white p-8 rounded-4xl shadow-lg border border-primary-100 relative overflow-hidden animate-scale-up">
                    <div className="flex items-center gap-4 mb-8">
                        <button 
                            onClick={() => setIsAddingProduct(false)}
                            className="w-10 h-10 rounded-full bg-primary-50 flex items-center justify-center hover:bg-primary-100 text-primary-600"
                        >
                            <ArrowLeft className="w-5 h-5" />
                        </button>
                        <h2 className="text-2xl font-black text-primary-800">إضافة منتج جديد</h2>
                    </div>

                    <div className="space-y-6 relative z-10">
                        {/* Image Upload Section */}
                        <div>
                        <label className="block text-sm font-bold text-primary-500 mb-2">صورة المنتج</label>
                        <input 
                            type="file" 
                            ref={fileInputRef}
                            onChange={handleImageUpload}
                            accept="image/*"
                            className="hidden"
                        />
                        {!newProduct.image ? (
                            <div 
                                onClick={triggerFileInput}
                                className="w-full h-48 border-2 border-dashed border-primary-300 rounded-3xl flex flex-col items-center justify-center cursor-pointer hover:border-brand-500 hover:bg-brand-50/50 transition-all group"
                            >
                                {isUploading ? (
                                    <div className="flex flex-col items-center animate-pulse">
                                        <Loader2 className="w-10 h-10 text-brand-500 animate-spin mb-2" />
                                        <p className="text-brand-600 font-bold text-sm">جاري رفع الصورة...</p>
                                    </div>
                                ) : (
                                    <>
                                        <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                                        <Upload className="w-8 h-8 text-primary-400 group-hover:text-brand-500" />
                                        </div>
                                        <p className="text-primary-500 font-bold group-hover:text-brand-600">اضغط لرفع صورة</p>
                                        <p className="text-xs text-primary-400 mt-1">PNG, JPG حتى 5MB</p>
                                    </>
                                )}
                            </div>
                        ) : (
                            <div className="relative w-full h-48 rounded-3xl overflow-hidden shadow-md group border border-primary-200">
                                <img src={newProduct.image} alt="Preview" className="w-full h-full object-cover" />
                                {isUploading && (
                                <div className="absolute inset-0 bg-primary-900/50 flex items-center justify-center z-20">
                                    <Loader2 className="w-10 h-10 text-white animate-spin" />
                                </div>
                                )}
                                <div className="absolute inset-0 bg-primary-900/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4 backdrop-blur-sm z-10">
                                <button onClick={triggerFileInput} className="p-2 bg-white rounded-full hover:bg-brand-500 hover:text-white transition-colors"><Upload className="w-5 h-5" /></button>
                                <button onClick={removeImage} className="p-2 bg-white rounded-full hover:bg-danger hover:text-white transition-colors"><X className="w-5 h-5" /></button>
                                </div>
                            </div>
                        )}
                        </div>

                        <div className="group">
                        <label className="block text-sm font-bold text-primary-500 mb-2">اسم المنتج</label>
                        <input 
                            type="text" 
                            value={newProduct.name}
                            onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
                            className="w-full p-4 border-2 border-primary-100 rounded-3xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-primary-700 bg-primary-50 focus:bg-white"
                            placeholder="مثال: بيتزا 4 فصول"
                        />
                        </div>

                        <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-bold text-primary-500 mb-2">السعر (د.ج)</label>
                            <input 
                            type="number" 
                            value={newProduct.price}
                            onChange={(e) => setNewProduct({...newProduct, price: Number(e.target.value)})}
                            className="w-full p-4 border-2 border-primary-100 rounded-3xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-primary-700 bg-primary-50 focus:bg-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-bold text-primary-500 mb-2">التصنيف</label>
                            <div className="relative">
                                <select 
                                value={newProduct.category}
                                onChange={(e) => setNewProduct({...newProduct, category: e.target.value as Category})}
                                className="w-full p-4 border-2 border-primary-100 rounded-3xl focus:border-brand-500 focus:ring-0 outline-none transition-colors font-bold text-primary-700 bg-primary-50 focus:bg-white appearance-none"
                                >
                                {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                                <ChevronRight className="absolute left-4 top-1/2 -translate-y-1/2 rotate-90 w-5 h-5 text-primary-400 pointer-events-none" />
                            </div>
                        </div>
                        </div>

                        <div className="bg-primary-50 p-4 rounded-3xl border border-primary-100">
                        <div className="flex justify-between items-center mb-3">
                            <label className="block text-sm font-bold text-primary-500">الوصف</label>
                            <button 
                            onClick={handleAIHelp}
                            disabled={isGenerating}
                            className="text-xs flex items-center gap-2 text-white font-bold bg-gradient-to-r from-purple-600 to-indigo-600 px-3 py-1.5 rounded-full hover:shadow-lg transition-all disabled:opacity-50"
                            >
                            <Sparkles className="w-3 h-3" /> 
                            {isGenerating ? 'جاري التفكير...' : 'اكتب لي يا ذكاء!'}
                            </button>
                        </div>
                        <textarea 
                            rows={4}
                            value={newProduct.description}
                            onChange={(e) => setNewProduct({...newProduct, description: e.target.value})}
                            className="w-full p-3 bg-white border border-primary-200 rounded-2xl focus:border-purple-500 outline-none transition-colors text-sm"
                            placeholder="اكتب وصفاً أو اطلب من مساعد كيمو..."
                        ></textarea>
                        </div>

                        <div className="pt-4 flex gap-4">
                            <button 
                                onClick={() => setIsAddingProduct(false)}
                                className="flex-1 bg-primary-100 text-primary-600 py-4 rounded-3xl font-bold text-lg hover:bg-primary-200 transition-colors"
                            >
                                إلغاء
                            </button>
                            <button 
                                onClick={saveProduct}
                                disabled={isSaving || isUploading}
                                className="flex-[2] bg-primary-900 text-white py-4 rounded-3xl font-bold text-lg hover:bg-brand-600 transition-colors shadow-lg hover:shadow-xl active:scale-98 disabled:opacity-50 disabled:cursor-not-allowed flex justify-center gap-2"
                            >
                                {isSaving ? <Loader2 className="animate-spin" /> : 'حفظ ونشر'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
          </div>
        )}

        {view === 'ORDERS' && (
          <div className="max-w-4xl mx-auto animate-fade-in-up">
            <h2 className="text-2xl font-black text-primary-800 mb-8 flex items-center gap-2">
                <ClipboardList className="w-8 h-8 text-brand-600" /> الطلبات الواردة
            </h2>

            {loadingOrders ? (
                <div className="flex justify-center items-center h-64"><Loader2 className="w-8 h-8 animate-spin text-primary-400" /></div>
            ) : orders.length === 0 ? (
                <div className="bg-white rounded-4xl p-16 text-center shadow-sm border border-primary-100">
                    <div className="w-24 h-24 bg-blue-50/20 rounded-full flex items-center justify-center mx-auto mb-6">
                        <ShoppingBag className="w-12 h-12 text-blue-300" />
                    </div>
                    <h3 className="text-xl font-bold text-primary-800 mb-2">لا توجد طلبات جديدة</h3>
                    <p className="text-primary-400">ستظهر الطلبات هنا عندما يقوم الزبائن بالشراء.</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {orders.map(order => (
                        <div key={order.id} className="bg-white p-6 rounded-4xl shadow-sm border border-primary-100 relative overflow-hidden">
                             {order.status === OrderStatus.PENDING && (
                                 <div className="absolute top-0 right-0 bg-warning text-warning-900 px-4 py-1 text-xs font-bold rounded-bl-3xl">
                                     طلب جديد
                                 </div>
                             )}
                             {order.status === OrderStatus.ACCEPTED_BY_STORE && (
                                 <div className="absolute top-0 right-0 bg-success text-white px-4 py-1 text-xs font-bold rounded-bl-3xl">
