        body: formData,
      }
    );

    const data = await res.json();
    if (data.secure_url) {
      return data.secure_url;
    } else {
      console.error("Cloudinary upload error:", data.error?.message || "Unknown error");
      return null;
    }
  } catch (error) {
    console.error("Error connecting to Cloudinary:", error);
    return null;
