                    >
                    <div className="w-28 h-28 shrink-0 rounded-2xl overflow-hidden bg-primary-100">
                        <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    </div>
                    <div className="flex-1 flex flex-col justify-between py-1">
                        <div>
                        <h3 className="font-bold text-lg text-primary-800 leading-tight mb-1">{product.name}</h3>
                        <p className="text-xs text-primary-500 line-clamp-2 leading-relaxed">{product.description}</p>
                        </div>
                        <div className="flex justify-between items-end mt-2">
                        <span className="font-black text-xl text-brand-600">{formatCurrency(product.price)}</span>
                        <button 
                            onClick={(e) => { e.stopPropagation(); addToCart(product); }}
                            className="bg-primary-900 text-white w-10 h-10 rounded-full hover:bg-brand-600 transition-colors shadow-lg shadow-primary-900/20 flex items-center justify-center active:scale-90"
                        >
                            <Plus className="w-5 h-5" />
                        </button>
                        </div>
                    </div>
                    </div>
                ))
              ) : (
                <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-primary-300">
                    <ShoppingBag className="w-12 h-12 text-primary-300 mx-auto mb-3" />
                    <p className="text-primary-400 font-medium">لا توجد منتجات حالياً لهذا المتجر</p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Modern Cart Bottom Sheet */}
      {showCart && (
        <>
            <div className="fixed inset-0 bg-primary-900/60 z-50 backdrop-blur-sm transition-opacity" onClick={() => setShowCart(false)}></div>
            <div className="fixed bottom-0 left-0 right-0 z-[60] bg-white rounded-t-5xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] max-h-[85vh] flex flex-col animate-slide-up">

                {/* Drag Handle */}
                <div className="w-full flex justify-center pt-4 pb-2" onClick={() => setShowCart(false)}>
                    <div className="w-12 h-1.5 bg-primary-200 rounded-full"></div>
                </div>

                <div className="p-6 flex-1 overflow-y-auto">
                    <div className="flex justify-between items-center mb-6">
                         <h2 className="text-2xl font-black text-primary-800">سلة المشتريات</h2>
                         <span className="bg-brand-100 text-brand-700 font-bold px-3 py-1 rounded-2xl text-sm">{cart.length} منتجات</span>
                    </div>

                    {cart.length === 0 ? (
                        <div className="text-center py-10 opacity-50">
                            <ShoppingCart className="w-16 h-16 mx-auto mb-4 text-primary-400" />
                            <p className="text-primary-500">سلتك فارغة</p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {cart.map((item) => (
                                <div key={item.product.id} className="flex items-center gap-4 bg-primary-50 p-3 rounded-3xl">
                                    <img src={item.product.image} className="w-16 h-16 rounded-2xl object-cover" />
                                    <div className="flex-1">
                                        <h4 className="font-bold text-primary-800">{item.product.name}</h4>
                                        <div className="flex items-center gap-1 text-brand-600 font-bold text-sm">
                                            {formatCurrency(item.product.price)}
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 bg-white px-2 py-1 rounded-2xl shadow-sm border border-primary-100">
                                        <button onClick={() => updateQuantity(item.product.id, -1)} className="p-1 text-primary-500 hover:text-danger"><Minus className="w-4 h-4"/></button>
                                        <span className="font-bold text-sm w-4 text-center text-primary-700">{item.quantity}</span>
                                        <button onClick={() => updateQuantity(item.product.id, 1)} className="p-1 text-primary-500 hover:text-success"><Plus className="w-4 h-4"/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {cart.length > 0 && (
                    <div className="p-6 bg-primary-50 border-t border-primary-100 pb-8">
                        <div className="space-y-2 mb-6 text-sm font-medium text-primary-600">
                             <div className="flex justify-between"><span>المجموع</span> <span className="text-primary-800">{formatCurrency(cartTotal)}</span></div>
                             <div className="flex justify-between"><span>التوصيل</span> <span className="text-brand-600">{formatCurrency(deliveryFee)}</span></div>
                             <div className="flex justify-between text-lg font-black text-primary-900 pt-2 border-t border-primary-200 mt-2">
                                <span>الإجمالي</span> <span>{formatCurrency(grandTotal)}</span>
                             </div>
                        </div>
                        <button 
                            onClick={handlePlaceOrder}
                            className="w-full bg-primary-900 text-white py-4 rounded-3xl font-bold text-lg hover:bg-brand-600 transition-colors shadow-xl shadow-primary-900/20 flex items-center justify-center gap-2 group"
                        >
                            <span>تأكيد الطلب</span>
                            <ArrowRight className="w-5 h-5 group-hover:translate-x-[-4px] transition-transform" />
                        </button>
                    </div>
                )}
            </div>
        </>
      )}
    </div>
  );
};

payload.text:
أهلاً بك مرة أخرى!

يبدو أن مشكلة عدم ظهور المنتجات ما زالت قائمة. هذا يعني أن التشخيص الأولي لم يكن كافياً، وأننا بحاجة إلى التعمق أكثر. المشكلة الأكثر احتمالاً لا تزال تتمحور حول **قواعد أمان Firebase Realtime Database** وكيفية تفاعل تطبيقك معها.

**السبب المحتمل وراء هذه المشكلة (مرة أخرى):**

عندما تسجل كـ "متجر" في تطبيقك، يحاول التطبيق حفظ ملفك الشخصي (اسمك، دورك، إلخ) في Firebase ضمن عقدة `stores/${user.uid}`. ولكن إذا فشلت هذه العملية (غالباً بسبب قواعد الأمان)، فإن التطبيق قد يستمر ويعتمد على التخزين المحلي (LocalStorage).

المشكلة هنا هي:
*   **قواعد المنتجات:** لديك قاعدة أمان للمنتجات تقول: `.write": "root.child('stores').child(auth.uid).exists()`. هذه القاعدة تعني أنك **لا تستطيع** إضافة منتج إلا إذا كان ملفك الشخصي كمتجر موجوداً فعلياً في عقدة `stores` في Firebase.
*   **التخزين المحلي ليس كافياً:** إذا فشل حفظ ملفك الشخصي كمتجر في Firebase، فلن تكون موجوداً في عقدة `stores`، وبالتالي ستفشل محاولاتك لإضافة المنتجات (حتى لو كانت تظهر مؤقتاً في LocalStorage الخاص بالمتجر، فلن تظهر للزبائن أو للمتجر نفسه بعد تحديث الصفحة لأنها لم تُحفظ في Firebase).

**الحل المقترح (مهم جداً):**

1.  **تأكيد تطبيق قواعد أمان Firebase:**
    **يجب عليك التأكد 100% أنك قمت بتطبيق قواعد الأمان التي أرسلتها لك سابقاً في لوحة تحكم Firebase.** هذه القواعد ضرورية جداً للسماح لتطبيقك بالعمل بشكل صحيح. سأكررها لك في النهاية.

2.  **تعديل شاشة التسجيل (AuthScreen.tsx):**
    سأقوم بتعديل كبير في `AuthScreen.tsx`. إذا حاول المتجر التسجيل وفشل حفظ ملفه الشخصي في Firebase (مثلاً بسبب قواعد الأمان)، فإن عملية التسجيل **يجب أن تفشل** ويعرض التطبيق رسالة خطأ للمستخدم. هذا سيجبرك على التأكد من أن قواعد Firebase مضبوطة بشكل صحيح قبل أن تتمكن من التسجيل كمتجر وإضافة المنتجات. هذا يزيل "السلوك المتساهل" الذي قد يجعلك تعتقد أن التسجيل نجح بينما فشل في Firebase.

3.  **إضافة المزيد من `console.log` للتشخيص:**
    سنضيف المزيد من رسائل `console.log` في كل من `StoreScreen.tsx` و `CustomerScreen.tsx` لتتبع البيانات بشكل أدق:
    *   متى يتم جلب المنتجات.
    *   ما هي المنتجات التي يتم جلبها قبل التصفية.
    *   ما هي المنتجات المصفاة التي تظهر للمتجر/الزبون.
    *   سجل أي أخطاء تحدث أثناء عملية الحفظ أو الجلب.

---

**الرجاء تنفيذ الخطوات التالية بدقة:**

1.  **حدث ملفاتك البرمجية** بالتعليمات البرمجية التي سأقدمها لك أدناه.
2.  **بعد تحديث التعليمات البرمجية، امسح بيانات المتصفح** (خاصة LocalStorage) أو استخدم وضع التصفح المتخفي (Incognito Mode) للتأكد من أنك تبدأ من الصفر بدون أي بيانات مخزنة محلياً قديمة.
3.  **افتح أدوات المطور (Developer Tools)** في متصفحك وانتقل إلى علامة التبويب "Console" (الطرفية).
4.  **حاول تسجيل حساب جديد كـ "متجر" (STORE):**
    *   إذا رأيت رسالة خطأ مثل "Database write failed..." في واجهة المستخدم، فهذا يعني أن قواعد أمان Firebase ليست صحيحة. **يجب عليك إصلاحها أولاً.**
    *   إذا نجح التسجيل، راقب رسائل `console.log` لتأكيد حفظ ملفك الشخصي كمتجر في Firebase.
5.  **بعد تسجيل الدخول كمتجر، حاول إضافة منتج جديد.** راقب الـ `console.log` عن كثب.
6.  **بعد إضافة المنتج، سجل الدخول كـ "زبون" (CUSTOMER)** وتصفح المنتجات. راقب الـ `console.log` هنا أيضاً.

---

### **قواعد أمان Firebase Realtime Database (النسخة النهائية والأكثر أماناً)**

**انسخ والصق هذه القواعد في قسم "Realtime Database" -> "Rules" في لوحة تحكم Firebase الخاصة بك، ثم اضغط على "Publish".**

```json
{
  "rules": {
    // Default: No read/write access unless explicitly granted below
    ".read": false,
    ".write": false,

    // Customers: Only the owner can read/write their own profile
    "customers": {
      "$uid": {
        ".read": "$uid === auth.uid",
        ".write": "$uid === auth.uid"
      }
    },
    // Stores:
    // Any authenticated user can read all store profiles (for customer screen)
    // Only the owner can read/write their own store profile
    "stores": {
      ".read": "auth.uid !== null",
      "$uid": {
