                            <ShoppingBag className="w-6 h-6" />
                          </div>
                          <div>
                            <p className="font-bold text-primary-800 text-sm">{order.customerName}</p>
                            <p className="text-[10px] text-primary-400">{new Date(order.timestamp).toLocaleTimeString('ar-DZ')}</p>
